('text.egyptian.tale_heavenly_cow','RELIGIOUS_COMPOSITION','lang.egy',NULL,NULL,'New Kingdom',NULL,NULL,NULL,NULL,NULL,'Rebellion against Ra, the Eye of Ra as Sekhmet, the red beer and the return to Hathor.'),
('text.chinese.zhouyi_xici','CLASSICAL_COMMENTARY','lang.lzh',NULL,NULL,'Received Warring States–Han layer; dating debated',NULL,NULL,NULL,NULL,NULL,'Xi Ci II opens its sequence of sage inventions with Baoxi making the eight trigrams and nets.'),
('text.chinese.sanwu_liji','LOST_WORK_KNOWN_FROM_QUOTATION','lang.lzh',NULL,NULL,'Three Kingdoms, attributed to Xu Zheng',NULL,NULL,NULL,NULL,NULL,'Quoted in Yiwen leiju juan 1 and Taiping yulan juan 1 for Pangu between the separating heaven and earth.'),
('text.irish.cath_maige_tuired','SAGA','lang.gle',NULL,NULL,'Medieval Irish; composition dates debated',NULL,NULL,NULL,NULL,NULL,'The Túatha Dé Danann prepare for and win the battle against the Fomoire; ends with the Morrígan''s prophecies.'),
('text.zoroastrian.mihr_yasht','HYMN','lang.ave',NULL,NULL,'Young Avestan; dating debated',NULL,NULL,NULL,NULL,NULL,'Hymn praising Mithra, lord of wide pastures, guardian of the contract, with a thousand ears and ten thousand eyes.'),
