INSERT OR IGNORE INTO myth_event_profiles(
    entity_id,event_type,time_layer,cause_summary,process_summary,result_summary,symbolism_summary
) VALUES
('event.egyptian.separation_geb_nut','COSMOGONIC_SEPARATION','Heliopolitan creation synthesis','Shu and Tefnet''s children, Geb and Nut, are earth and sky.','Shu holds earth and sky apart.','Earth and sky stay separated.','UCL notes the separation had to be enforced to prevent further divine offspring.'),
('event.egyptian.osiris_murder_restoration','DIVINE_MURDER_AND_RESTORATION','Osiris cycle synthesis','Seth''s jealousy of his brother Osiris.','Seth murders and dismembers Osiris and takes his place as king; Isis collects the limbs.','Isis revives the body enough to conceive Horus.','The many ancient versions are not merged into one master text here.'),
('event.egyptian.heavenly_cow_punishment','DIVINE_PUNISHMENT','New Kingdom composition','People rebel against the sun-god Ra.','Ra sends his Eye; as Sekhmet she almost annihilates humankind.','The gods colour a lake of beer red; she drinks it and reverts to Hathor.','The transformation is a narrative change of character, not a database identity merge.'),
('event.egyptian.weighing_heart_ani','FUNERARY_JUDGMENT','New Kingdom Book of the Dead papyrus','Ani is judged in the Hall of Judgment.','Anubis steadies the balance; Thoth, as baboon and as ibis-headed scribe, attends and records.','The museum record describes the weighing; the outcome is not modelled here.','Scene-level description from one papyrus frame.'),
('event.japanese.onogoro_creation','LAND_CREATION','Kojiki, upper scroll','The heavenly deities command the pair to make and consolidate the drifting land.','Standing on the Floating Bridge of Heaven they stir the brine with the jewelled spear.','Brine dripping from the spear piles up into Onogoro Island.','The Nihon Shoki''s differing account is not merged here.'),
('event.japanese.izanagi_visits_yomi','UNDERWORLD_JOURNEY','Kojiki, upper scroll','Izanami dies after giving birth to the fire deity.','Izanagi follows her to Yomi and asks her to come back because their lands are unfinished.','She answers that he came too late, for she has eaten of Yomi''s hearth.','Later flight scenes are summarized only where the cited sections support them.'),
('event.japanese.izanagi_purification','PURIFICATION_AND_BIRTH','Kojiki, upper scroll','Izanagi returns polluted from Yomi.','Deities are born as he bathes; the last three come from his eyes and nose.','Amaterasu, Tsukuyomi and Susanoo are born.','Chamberlain''s notes supply the standard identifications of the three deities.'),
('event.norse.binding_of_fenrir','BINDING','Gylfaginning','The gods fear the growing wolf.','Týr places his hand in the wolf''s mouth as a pledge while the wolf is bound.','When the wolf is not released it bites off Týr''s hand.','Snorri''s prose account only.'),
('event.norse.slaying_of_ymir','COSMOGONIC_SACRIFICE','Gylfaginning','Ymir arises where rime meets heat in Ginnungagap.','The sons of Borr kill Ymir.','Earth is made from his flesh, sea from his blood, rocks from his bones and the sky from his skull.','Snorri''s prose synthesis; eddic poem witnesses are separate.'),
('event.norse.death_of_baldr','DIVINE_DEATH','Gylfaginning','Baldr dreams of danger to his life.','Frigg takes oaths from all things not to harm him but leaves out the mistletoe.','Baldr is killed with a shoot of mistletoe.','Snorri''s prose account; the later course of the episode is not itemized here.'),
('event.mexica.birth_of_huitzilopochtli','DIVINE_BIRTH_AND_COMBAT','Florentine Codex, Book 3','Coatlicue conceives from a ball of feathers; her children plan to kill her.','Huitzilopochtli is born fully armed on Coatepec.','He kills Coyolxauhqui and scatters the Centzon Huitznahua.','Scholars link the account to the layout of the Templo Mayor; that reading is interpretive.'),
('event.mexica.quetzalcoatl_tollan_end','DOWNFALL_AND_DEPARTURE','Florentine Codex, Book 3','Sorcerers, among them Titlacauan (Tezcatlipoca), come to Quetzalcoatl.','His glory at Tollan comes to an end.','Quetzalcoatl departs; his followers suffer on the journey.','Chapter-level summary of a sixteenth-century compilation.'),
('event.sumerian.enki_ninhursag','CURSE_AND_HEALING','Sumerian literary composition','Enki eats the plants that grew in Dilmun.','Ninhursaĝa curses him and he falls ill.','She brings forth deities to heal the ailing parts of his body.','Composite-text summary; manuscript variants not modelled.'),
('event.sumerian.nanna_journey','DIVINE_JOURNEY','Sumerian literary composition','Nanna-Suen sets his mind on his father''s city.','He loads a boat with gifts and travels to Nibru.','Enlil grants him abundance to take back to Urim.','Often read as reflecting offerings carried between cult centres; that reading is interpretive.'),
('event.sumerian.gilgamesh_huwawa','HEROIC_EXPEDITION','Sumerian literary composition','Gilgameš wishes to make a name in the mountains.','Enkidu urges that Utu be told; Utu accepts Gilgameš''s tears and grants him warriors as guides.','They confront Ḫuwawa.','Version A composite text only.'),
('event.chinese.fuxi_makes_trigrams','CULTURAL_ORIGIN','Xi Ci II sequence of sages','Baoxi rules all under heaven in antiquity.','He observes images in heaven, patterns on earth, the markings of birds and beasts, and things near and far.','He first makes the eight trigrams and knots cords into nets.','The trigrams communicate with spirit-like virtue and classify the dispositions of the myriad things.'),
('event.chinese.battle_of_zhuolu','LEGENDARY_BATTLE','Shiji legendary-sovereign narrative','Chiyou rebels and does not obey the ruler''s command.','Xuanyuan levies the lords'' armies and fights Chiyou in the wilds of Zhuolu.','Chiyou is captured and killed; the lords honour Xuanyuan as Son of Heaven.','Recorded as what the Shiji says, not as a dated historical battle.'),
('event.chinese.pangu_heaven_earth','COSMOGONIC_SEPARATION','Sanwu liji as quoted in Tang and Song encyclopedias','Heaven and earth are an undivided chaos like a hen''s egg, with Pangu born inside.','After 18,000 years the clear yang becomes heaven and the murky yin becomes earth; each day heaven rises, earth thickens and Pangu grows by one zhang.','Heaven is extremely high, earth extremely deep and Pangu extremely tall; afterwards come the Three Sovereigns.','The later motif of Pangu''s body becoming the world belongs to a different text and is not merged here.'),
('event.chinese.nezha_fights_wukong','DIVINE_COMBAT','Ming novel (later literary reception)','Sun Wukong leaves his post and calls himself Great Sage Equal to Heaven.','Nezha and Wukong both take three heads and six arms; Wukong turns a hair into a double and strikes Nezha from behind.','Nezha retreats in pain and reports back to Heavenly King Li.','A novel''s literary episode, kept in the later-reception layer.'),
('event.irish.second_battle_mag_tuired','DIVINE_WAR','Medieval Irish saga','The Túatha Dé Danann rise against Fomorian oppression.','Preparations at Tara and Samain; the battle at Mag Tuired; Lug faces Balor.','The Fomoire are routed; the Morrígan proclaims the victory and prophesies.','Saga narrative; not a historical battle record.'),
('event.slavic.kyiv_idols_980','CULT_FOUNDATION_RECORD','Primary Chronicle annal 980','Volodimer begins to reign alone in Kyiv.','He sets up wooden idols on the hill outside the palace hall, and people make offerings to them.','The idols stand until the conversion recorded in 988.','A Christian chronicle''s account of pre-Christian cult; its perspective is not neutral.'),
('event.slavic.idols_cast_down_988','CULT_SUPPRESSION_RECORD','Primary Chronicle annal 988','Volodimer''s baptism.','Idols are cut down or burned; Perun is tied to a horse''s tail, beaten and dragged to the Dnieper.','Perun''s image is thrown into the river.','Recorded from the converting side; not a neutral description of Slavic religion.'),
('event.zoroastrian.sixteen_lands','CREATION_AND_COUNTER_CREATION','Videvdad 1','Ahura Mazda makes every land dear to its people.','For each good land Angra Mainyu sets a plague against it.','Sixteen lands and sixteen counter-creations are listed.','Darmesteter reads the list as a religious geography of Iran, not a migration record.'),
('event.hawaiian.pele_journey','DIVINE_MIGRATION','Hawaiian oral history as presented by NPS','Pele seeks a suitable home for her fire and family.','She voyages from Kahiki and moves southeast through the islands.','She settles in Halemaʻumaʻu at the summit of Kīlauea, where she is said still to reside.','NPS notes that moʻolelo versions vary, in some cases significantly.'),
('event.maori.separation_rangi_papa','COSMOGONIC_SEPARATION','Common thread across iwi traditions (Te Ara)','Ranginui and Papatūānuku lie joined, their children born in darkness between them.','The children act to separate their parents.','Light enters the world; the children become atua of different parts of nature.','Te Ara stresses considerable diversity among tribal versions; no single standard version is built.');

