INSERT OR IGNORE INTO stories(
    id,canonical_title,title_zh,story_type,primary_civilization_id,summary_zh,summary_en,themes_json,evidence_status,access_level,reading_minutes,featured_order,editorial_note,created_at,updated_at
) VALUES
('story.egyptian.heliopolitan_family','From Atum to Horus — a family of Egyptian gods','从阿图姆到荷鲁斯：埃及众神的一家','GENEALOGICAL_ACCOUNT','civ.egyptian','UCL 数字埃及把零散的古代文献整理成一个神族谱系：太阳神阿图姆生出舒与泰芙努特，他们又生出大地之神盖布与天空女神努特；舒把天地分开。后来塞特杀害兄弟奥西里斯，伊西斯收集遗体并怀上荷鲁斯。这是一份学术综述，不是某一部古代文献的原文顺序。','UCL Digital Egypt orders scattered ancient references into one divine family: the sun-god Atum brings forth Shu and Tefnet, who produce Geb (earth) and Nut (sky); Shu holds them apart. Later Seth murders his brother Osiris, and Isis gathers the body and conceives Horus. It is a scholarly synthesis, not the sequence of a single ancient text.','["创世", "家族", "天地分离", "奥西里斯"]','SOURCE_BACKED','PUBLIC_CONTEXT',6,300,'学术综述层；古代文本见证尚未逐条拆分，各神亲属关系以 UCL 页面的表述为准。','2026-10-09T00:30:00Z','2026-10-09T00:30:00Z'),
('story.egyptian.heavenly_cow','The Eye of Ra becomes Sekhmet — Tale of the Heavenly Cow','拉的眼睛化作塞赫麦特：天牛之书','MYTHIC_NARRATIVE','civ.egyptian','人类反叛太阳神拉。拉把自己的“眼睛”派出去惩罚人类，她化作塞赫麦特，几乎把人类消灭。众神把一湖啤酒染成血红色，她喝醉后恢复成慈爱的哈托尔。','Humankind rebels against the sun-god Ra. He sends out his Eye to punish them; as Sekhmet she almost wipes humanity out, until the gods dye a lake of beer blood-red and she drinks, growing gentle again as Hathor.','["惩罚", "拉的眼睛", "塞赫麦特", "哈托尔"]','SOURCE_BACKED','PUBLIC_CONTEXT',4,305,'依据 UCL 对新王国宗教文献《天牛之书》的概述；塞赫麦特与哈托尔在数据库中仍是两个实体。','2026-10-09T00:30:00Z','2026-10-09T00:30:00Z'),
('story.egyptian.weighing_heart_ani','Weighing the heart — Anubis and Thoth in the Papyrus of Ani','称量心脏：阿尼纸草中的阿努比斯与托特','RITUAL_ORIGIN','civ.egyptian','大英博物馆藏《阿尼纸草》第3框画着审判大厅：天平一边放着阿尼的心脏，另一边是代表玛阿特的羽毛。胡狼头的阿努比斯扶稳天平，托特既以狒狒形象坐在天平上，又以朱鹭头书吏的形象准备记录结果。','British Museum Papyrus of Ani, frame 3, shows the Hall of Judgment: Ani''s heart in one pan, a feather representing Maat in the other. Jackal-headed Anubis steadies the balance, and Thoth appears both as a baboon on top of it and as the ibis-headed scribe ready to record the result.','["审判", "冥界", "阿努比斯", "托特", "玛阿特"]','SOURCE_BACKED','PUBLIC_CONTEXT',4,310,'依据博物馆对单件纸草画面的描述；结果判定与怪兽阿米特未在本框记录中出现，不补写。','2026-10-09T00:30:00Z','2026-10-09T00:30:00Z'),
('story.egyptian.mourning_sisters','Two mourning goddesses — Isis and Nephthys','两位哀悼的女神：伊西斯与奈芙蒂斯','RITUAL_ORIGIN','civ.egyptian','大都会艺术博物馆的一对托勒密时期木像：奈芙蒂斯跪着，举手掩面哀悼；另一尊是同样姿势的伊西斯。博物馆说明，在古埃及的图像中，这两位女神常守在奥西里斯遗体的两侧。','A Ptolemaic pair of wooden figures at the Met: Nephthys kneels with a hand raised before her face in mourning, and a companion figure shows Isis. The museum notes that the two mourning goddesses accompany the body of Osiris in Egyptian representations.','["哀悼", "丧葬", "伊西斯", "奈芙蒂斯"]','SOURCE_BACKED','PUBLIC_CONTEXT',3,315,'物质见证层：依据博物馆藏品说明；“放在棺椁两端”是博物馆的推测。','2026-10-09T00:30:00Z','2026-10-09T00:30:00Z'),
('story.japanese.izanagi_izanami','Izanagi and Izanami — making the land, Yomi and purification','伊邪那岐与伊邪那美：造岛、黄泉与禊祓','CREATION_ACCOUNT','civ.japanese_shinto','天神命伊邪那岐与伊邪那美巩固漂浮的大地。两神站在天浮桥上，用天沼矛搅动海水，滴下的盐水堆成淤能碁吕岛。伊邪那美生下火神后被烧伤而死；伊邪那岐追到黄泉，她却说已经吃了黄泉的食物。伊邪那岐回来后洗净身体，最后从左眼、右眼和鼻子生出天照大神、月读和须佐之男。','The heavenly deities command Izanagi and Izanami to consolidate the drifting land. From the Floating Bridge of Heaven they stir the brine with a jewelled spear, and the drops become Onogoro Island. Izanami dies after bearing the fire deity; Izanagi follows her to Yomi, but she has already eaten of its hearth. Returning, he purifies himself, and from his left eye, right eye and nose are born Amaterasu, Tsukuyomi and Susanoo.','["创世", "黄泉", "禊祓", "三贵子"]','SOURCE_BACKED','PUBLIC_CONTEXT',7,320,'依据张伯伦 1882 年英译《古事记》的第三至第十节；《日本书纪》的不同说法另行保存，不合并。','2026-10-09T00:30:00Z','2026-10-09T00:30:00Z'),
('story.norse.vanir_family','Njörðr, Freyr and Freyja — the Vanir family','华纳神族：尼奥尔德、弗雷与芙蕾雅','MYTHIC_NARRATIVE','civ.norse','尼奥尔德住在诺欧通，掌管风和海，原本在华纳海姆长大，作为人质来到阿萨神族。他的儿子弗雷掌管雨水、阳光和丰收；女儿芙蕾雅住在弗尔克范格，每次出征都分走一半战死者，乘坐两只猫拉的车。弗雷后来为了娶葛德，交出了自己的宝剑。','Njörðr lives at Nóatún and rules wind and sea; raised in Vanaheim, he came to the Æsir as a hostage. His son Freyr rules rain, sunshine and harvests; his daughter Freyja lives at Fólkvangr, takes half the slain and drives a chariot pulled by two cats. Later Freyr gives away his sword to win Gerðr.','["华纳神族", "海洋", "丰收", "芙蕾雅"]','SOURCE_BACKED','PUBLIC_CONTEXT',5,330,'依据《欺骗古鲁菲》第23、24、37章；诗体埃达中的对应诗篇另行登记。','2026-10-09T00:30:00Z','2026-10-09T00:30:00Z'),
('story.norse.tyr_fenrir','Týr''s hand and the binding of Fenrir','提尔的手：束缚芬里尔','MYTHIC_NARRATIVE','civ.norse','提尔是众神中最勇敢的一位。众神要捆住越长越大的狼芬里尔，狼要求有人把手放进它嘴里作担保。只有提尔伸出了右手；当狼发现自己挣脱不开，就咬断了他的手。所以提尔只有一只手。','Týr is the boldest of the gods. When they set out to bind the growing wolf Fenrir, the wolf demands a hand in its mouth as a pledge. Only Týr offers his right hand; when the wolf finds it cannot break free, it bites the hand off — and so Týr is one-handed.','["芬里尔", "勇气", "誓约"]','SOURCE_BACKED','PUBLIC_CONTEXT',4,335,'依据《欺骗古鲁菲》第25、34章；芬里尔在诸神黄昏中的结局见既有故事。','2026-10-09T00:30:00Z','2026-10-09T00:30:00Z'),
('story.norse.heimdall_watchman','Heimdallr, watchman of the gods','海姆达尔：众神的守望者','MYTHIC_NARRATIVE','civ.norse','海姆达尔住在彩虹桥边的希敏约格，替众神守着桥，防备山巨人。他睡得比鸟还少，夜里能看见一百里远，连草和羊毛生长的声音都听得见。他有一支加拉尔号角，吹响时所有世界都能听到。人们还说他是九位姐妹母亲的儿子。','Heimdallr lives at Himinbjörg beside the rainbow bridge Bifröst and guards it for the gods against the mountain-giants. He needs less sleep than a bird, sees a hundred leagues by night, and hears grass and wool growing. His horn Gjallarhorn can be heard in all worlds, and he is called the son of nine mothers who were sisters.','["守望者", "号角", "彩虹桥"]','SOURCE_BACKED','PUBLIC_CONTEXT',4,340,'依据《欺骗古鲁菲》第27章。','2026-10-09T00:30:00Z','2026-10-09T00:30:00Z'),
('story.norse.ymir_world','Ymir and the shaping of the world','尤弥尔与世界的形成','MYTHIC_NARRATIVE','civ.norse','太初有一道深渊，北方的寒霜遇到南方的热气，化出巨人尤弥尔。后来奥丁和他的兄弟维利、维杀死了尤弥尔，用他的身体造出世界：肉成了大地，血成了海洋和湖泊，骨头成了山石，头骨成了天空。','In the beginning there is a great void where rime from the north meets heat from the south, and from it the giant Ymir arises. Later Odin and his brothers Vili and Vé kill Ymir and build the world from his body: his flesh becomes the earth, his blood the sea and lakes, his bones the rocks, his skull the sky.','["创世", "巨人", "世界身体"]','SOURCE_BACKED','PUBLIC_CONTEXT',4,345,'依据《欺骗古鲁菲》第5–8章；《女巫的预言》等诗歌见证另行对读。','2026-10-09T00:30:00Z','2026-10-09T00:30:00Z'),
('story.norse.frigg_baldr','Frigg''s oaths and the death of Baldr','弗丽嘉的誓言与巴德尔之死','MYTHIC_NARRATIVE','civ.norse','弗丽嘉是奥丁的妻子，知道一切命运。她的儿子巴德尔梦见自己有危险，她便让火、水、金属、石头、草木和野兽都发誓不伤害他——唯独漏掉了一株幼小的槲寄生。巴德尔最后正是被槲寄生杀死的。','Frigg, Odin''s wife, knows all fates. When her son Baldr dreams of danger, she makes fire, water, metals, stones, plants and beasts swear not to harm him — all except a young shoot of mistletoe. In the end it is mistletoe that kills Baldr.','["巴德尔", "誓言", "命运"]','SOURCE_BACKED','PUBLIC_CONTEXT',4,350,'依据《欺骗古鲁菲》第20、49章；之后的冥界求情与报复情节尚未逐段登记。','2026-10-09T00:30:00Z','2026-10-09T00:30:00Z'),
('story.mexica.birth_huitzilopochtli','The birth of Huitzilopochtli on Serpent Mountain','蛇山上的诞生：维齐洛波奇特利','DIVINE_COMBAT','civ.mexica','科阿特利库埃在蛇山打扫时，一团羽毛飘落，她把它塞在腰间，因此怀孕。女儿科约尔沙乌基认为这是耻辱，带着四百个兄弟要杀死母亲。就在他们冲上山顶时，维齐洛波奇特利全副武装地出生，砍下科约尔沙乌基的头，把兄弟们赶散。','While sweeping on Coatepec, Coatlicue picks up a ball of feathers, tucks it at her waist and conceives. Her daughter Coyolxauhqui, shamed, leads the four hundred brothers to kill their mother. As they reach the summit, Huitzilopochtli is born fully armed, beheads Coyolxauhqui and scatters the brothers.','["诞生", "战神", "蛇山", "墨西加"]','SOURCE_BACKED','PUBLIC_CONTEXT',5,360,'依据《佛罗伦萨手抄本》第三卷第1章（萨阿贡编纂，16世纪）；学者把这段故事与大神庙布局相联系属于解释层。','2026-10-09T00:30:00Z','2026-10-09T00:30:00Z'),
('story.mexica.quetzalcoatl_tollan','Quetzalcoatl and Titlacauan at Tollan','图拉的羽蛇神与蒂特拉卡瓦','MYTHIC_NARRATIVE','civ.mexica','《佛罗伦萨手抄本》第三卷讲述图拉的大法师羽蛇神。巫师们来到他身边，其中一位叫蒂特拉卡瓦，也就是特斯卡特利波卡；他们带来的种种征兆让羽蛇神的荣光走向终结。羽蛇神离开时，随行的人在两座雪山之间冻死。','Florentine Codex Book 3 tells of Quetzalcoatl, a great wizard at Tollan. Sorcerers come to him — among them Titlacauan, also called Tezcatlipoca — and their portents bring his glory to an end. As he departs, his followers freeze to death between two snow-capped volcanoes.','["羽蛇神", "特斯卡特利波卡", "图拉", "离去"]','SOURCE_BACKED','PUBLIC_CONTEXT',4,365,'依据第三卷第2–5、14章的章节标题与概要；各章细节尚未逐段建模。','2026-10-09T00:30:00Z','2026-10-09T00:30:00Z'),
('story.mexica.templo_mayor_twin_shrines','Two gods on one pyramid — the Templo Mayor','一座金字塔上的两位神：大神庙','TRADITION_OVERVIEW','civ.mexica','特诺奇蒂特兰的大神庙顶上并立着两座神殿：南边供奉太阳战神、墨西加人的守护神维齐洛波奇特利，北边供奉与农业相连的雨神特拉洛克。墨西哥国家人类学与历史研究所说，神庙始建于1325年，此后多次重建与扩建。','Atop the Templo Mayor of Tenochtitlan stood two shrines: on the south, Huitzilopochtli, solar god of war and patron of the Mexica; on the north, Tlaloc, god of rain linked to agriculture. INAH says the first small temple was built at the city''s founding in 1325 and was rebuilt and enlarged many times.','["大神庙", "战争与雨水", "考古遗址"]','SOURCE_BACKED','PUBLIC_CONTEXT',3,370,'现实遗址层：依据墨西哥国家人类学与历史研究所（INAH）遗址博物馆的公开说明；不推测坐标。','2026-10-09T00:30:00Z','2026-10-09T00:30:00Z'),
('story.maya.divine_images','Three Maya gods in stone, clay and glyph','石头、陶盘与文字中的三位玛雅神','TRADITION_OVERVIEW','civ.maya','三份独立见证，各讲一位玛雅神：奇琴伊察的卡斯蒂略金字塔又叫“库库尔坎神庙”；大都会博物馆的一只陶盘上，雨神恰克半身浸在水中；同一博物馆的展览介绍年老的天神伊察姆纳和他的鸟形化身。三份见证分开阅读，不拼成一个统一神话。','Three separate witnesses, one god each: Chichen-Itza''s El Castillo is also called the Temple of Kukulkan; a Met plate shows the rain god Chahk waist-deep in water; and a Met exhibition presents the aged sky god Itzamnaaj and his bird avatar. They are read separately, not stitched into one myth.','["库库尔坎", "恰克", "伊察姆纳", "物质见证"]','SOURCE_BACKED','PUBLIC_CONTEXT',5,375,'三个版本分别来自联合国教科文组织遗产记录与大都会艺术博物馆的两份说明；不把玛雅与墨西加的羽蛇神合并。','2026-10-09T00:30:00Z','2026-10-09T00:30:00Z'),
('story.sumerian.enki_ninhursag','Enki and Ninhursaĝa in Dilmun','恩基与宁胡尔萨格：迪尔蒙的植物','MYTHIC_NARRATIVE','civ.sumerian','故事从纯净的迪尔蒙开始。恩基吃掉了那里长出的植物，宁胡尔萨格怒而诅咒他，恩基因此病倒。后来宁胡尔萨格回心转意，为恩基身上每一处病痛生出一位神灵，把他治好。','The story begins in pure Dilmun. Enki eats the plants that have grown there; Ninhursaĝa curses him in anger, and he falls ill. Later she relents and brings forth a deity for each ailing part of his body, healing him.','["迪尔蒙", "诅咒", "治愈"]','SOURCE_BACKED','PUBLIC_CONTEXT',4,380,'依据 ETCSL 1.1.1 综合文本；植物与疗愈神的名单尚未逐项建模。','2026-10-09T00:30:00Z','2026-10-09T00:30:00Z'),
('story.sumerian.nanna_journey','Nanna-Suen sails to Nibru','月神南纳航向尼普尔','MYTHIC_NARRATIVE','civ.sumerian','月神南纳想念父亲恩利尔的城市尼普尔，便装满一船礼物，沿河航行前往。到了尼普尔，恩利尔欢迎他，赐给他满船的丰饶，让他带回自己的城市乌尔。','The moon god Nanna-Suen longs for Nibru, the city of his father Enlil. He loads a boat with gifts and sails there; Enlil welcomes him and grants him abundance to carry home to his own city, Urim.','["月神", "航行", "父子"]','SOURCE_BACKED','PUBLIC_CONTEXT',4,385,'依据 ETCSL 1.5.1 综合文本；沿途城市与礼物清单尚未逐项建模。','2026-10-09T00:30:00Z','2026-10-09T00:30:00Z'),
('story.sumerian.gilgamesh_huwawa_utu','Utu helps Gilgameš set out against Ḫuwawa','太阳神乌图与吉尔伽美什的远征','MYTHIC_NARRATIVE','civ.sumerian','吉尔伽美什决定进山建立名声。伙伴恩奇都提醒他：山是太阳神乌图的事，得先告诉乌图。吉尔伽美什向乌图祈求，乌图接受了他的眼泪作为礼物，赐给他七位勇士做向导，去面对山中的守护者胡瓦瓦。','Gilgameš resolves to make his name in the mountains. His companion Enkidu warns that the mountains are Utu''s concern, so the sun god must be told. Gilgameš prays, and Utu accepts his tears as a gift and grants him seven warriors as guides to face Ḫuwawa, the guardian of the mountains.','["乌图", "吉尔伽美什", "远征"]','SOURCE_BACKED','PUBLIC_CONTEXT',4,390,'依据 ETCSL 1.8.1.5（版本A）；与后来阿卡德语史诗的情节分开保存。','2026-10-09T00:30:00Z','2026-10-09T00:30:00Z'),
('story.chinese.fuxi_eight_trigrams','Fuxi makes the eight trigrams','伏羲始作八卦','MYTHIC_NARRATIVE','civ.chinese_ancient','《周易·系辞下》说：古时包牺氏（伏羲）治理天下，他抬头观察天象，低头观察地理，看鸟兽身上的纹理和各地的物产，近取自身、远取万物，于是开始画出八卦；他又把绳子打结做成网，用来打猎捕鱼。','The Xi Ci II says that when Baoxi (Fuxi) ruled in antiquity, he looked up at heaven and down at the earth, studied the markings of birds and beasts and the land, drew on his own body and on distant things, and first made the eight trigrams; he also knotted cords into nets for hunting and fishing.','["伏羲", "八卦", "文明起源"]','SOURCE_BACKED','PUBLIC_CONTEXT',4,400,'依据《系辞下》第二章；“包牺即伏羲”采用传统注疏的读法。','2026-10-09T00:30:00Z','2026-10-09T00:30:00Z'),
('story.chinese.huangdi_chiyou','The Yellow Emperor and Chiyou at Zhuolu','黄帝战蚩尤：涿鹿之战','DIVINE_COMBAT','civ.chinese_ancient','《史记·五帝本纪》说：神农氏衰落，诸侯互相攻伐，轩辕操练军队征讨不服者。蚩尤最为暴虐，作乱不听帝命。轩辕征召诸侯之兵，在涿鹿的原野擒杀蚩尤，诸侯于是尊他为天子，这就是黄帝。','The Shiji''s Annals of the Five Emperors say that as Shennong''s house declined and the lords fought one another, Xuanyuan trained troops. Chiyou, the most violent, rebelled against the ruler''s command; Xuanyuan levied the lords'' armies, captured and killed him in the wilds of Zhuolu, and was honoured as Son of Heaven — the Yellow Emperor.','["黄帝", "蚩尤", "战争", "上古帝王"]','SOURCE_BACKED','PUBLIC_CONTEXT',4,405,'依据《史记·五帝本纪》；司马迁以史笔叙述，本站只登记文本所述，不作历史真实性断言。','2026-10-09T00:30:00Z','2026-10-09T00:30:00Z'),
('story.chinese.pangu_sanwu_liji','Pangu between heaven and earth','盘古开天地：《三五历纪》佚文','CREATION_ACCOUNT','civ.chinese_ancient','三国吴人徐整的《三五历纪》已经失传，只在后世类书中留有引文。《艺文类聚》卷一引它说：天地未分时混沌如鸡蛋，盘古生在其中；一万八千年后天地开辟，清者为天、浊者为地；天每天高一丈，地每天厚一丈，盘古每天长一丈，又过一万八千年，天极高、地极深、盘古极长。','Xu Zheng''s Sanwu liji is lost, surviving only in later encyclopedias. Yiwen leiju juan 1 quotes it: before heaven and earth parted, all was chaos like a hen''s egg, and Pangu was born inside; after 18,000 years they opened, clear becoming heaven and murky becoming earth; each day heaven rose a zhang, earth thickened a zhang and Pangu grew a zhang, until after another 18,000 years heaven was highest, earth deepest and Pangu tallest.','["盘古", "创世", "天地开辟"]','SOURCE_BACKED','PUBLIC_CONTEXT',4,410,'依据《艺文类聚》卷一所引《三五历纪》，并以《太平御览》卷一的引文对照；盘古身体化生万物另见他书，不在此合并。','2026-10-09T00:30:00Z','2026-10-09T00:30:00Z'),
('story.chinese.nezha_wukong','Nezha against Sun Wukong (Journey to the West, ch. 4)','哪吒大战孙悟空：《西游记》第四回','DIVINE_COMBAT','civ.chinese_folk','孙悟空嫌弼马温官小，回花果山自称齐天大圣。托塔李天王与哪吒三太子奉命捉拿。哪吒变出三头六臂，悟空也变三头六臂；悟空拔毫毛变出分身，真身绕到背后打中哪吒，哪吒负痛败走。','Finding his stable post too lowly, Sun Wukong returns home and calls himself Great Sage Equal to Heaven. Heavenly King Li and his third son Nezha are sent to seize him. Nezha takes three heads and six arms; Wukong does the same, then turns a hair into a double and strikes Nezha from behind, and Nezha retreats in pain.','["哪吒", "孙悟空", "变化", "明代小说"]','SOURCE_BACKED','PUBLIC_CONTEXT',4,415,'明代小说《西游记》属于后世文学接受层，不当作古代神话见证；哪吒闹海等故事出自其他作品，未在此合并。','2026-10-09T00:30:00Z','2026-10-09T00:30:00Z'),
('story.irish.second_battle_mag_tuired','The Second Battle of Mag Tuired','第二次马格图雷德之战：达格达、莫莉甘、布里格与鲁格','DIVINE_COMBAT','civ.irish','中世纪爱尔兰传说《第二次马格图雷德之战》：达格达拥有“没有人吃不饱”的大锅；“百艺之主”鲁格来到塔拉；萨温节时达格达在河边遇见莫莉甘；布里格为战死的儿子哀哭，是爱尔兰第一次听到哀歌；鲁格用投石击毁巴洛尔的毒眼；战后莫莉甘向全爱尔兰宣告胜利。','The medieval Irish saga Cath Maige Tuired: the Dagda''s cauldron leaves no one unsatisfied; Lug, master of all arts, comes to Tara; at Samain the Dagda meets the Morrígan by the river; Bríg keens for her slain son, the first keening in Ireland; Lug''s sling stone drives Balor''s deadly eye through his head; and the Morrígan proclaims the victory across Ireland.','["达格达", "莫莉甘", "布里格", "鲁格", "战争"]','SOURCE_BACKED','PUBLIC_CONTEXT',7,420,'依据 Elizabeth A. Gray 1982 年校译本（CELT T300010）的段落编号；译文受版权保护，只发布定位与独立概述。','2026-10-09T00:30:00Z','2026-10-09T00:30:00Z'),
('story.slavic.kyiv_idols','The idols on the Kyiv hill — Perun and Mokosh','基辅山岗上的神像：佩伦与莫科什','RITUAL_ORIGIN','civ.slavic','《往年纪事》980 年条：弗拉基米尔在基辅宫殿外的山岗上立起神像——银头金须的木雕佩伦，还有霍尔斯、达日博格、斯特里博格、西马尔格尔和莫科什，人们向它们献祭。988 年他受洗后下令推倒神像，佩伦被绑在马尾上拖下山，丢进第聂伯河。','The Primary Chronicle''s annal for 980: Volodimer sets up idols on the hill outside his Kyiv palace — a wooden Perun with a silver head and golden moustache, then Khors, Dazhbog, Stribog, Simargl and Mokosh — and people make offerings to them. After his baptism in 988 he has them cast down; Perun is tied to a horse''s tail, dragged down the hill and thrown into the Dnieper.','["佩伦", "莫科什", "神像", "编年史"]','SOURCE_BACKED','PUBLIC_CONTEXT',4,425,'依据《往年纪事》980 与 988 年条；编年史由皈依后的基督教修士编写，对旧信仰的描述带有立场；莫科什在此只有名字。','2026-10-09T00:30:00Z','2026-10-09T00:30:00Z'),
('story.zoroastrian.mihr_yasht','Mithra of the wide pastures — the Mihr Yasht','广阔牧场之主密特拉：《密赫尔颂》','TEXT_FRAGMENT','civ.zoroastrian','阿维斯塔第十颂《密赫尔颂》：阿胡拉·马兹达说，他创造密特拉时，使他与自己同样值得祭祀和祈祷；对密特拉说谎、背弃契约的人会给整个国家带来死亡；密特拉有千只耳朵、万只眼睛，在不朽的快马太阳之前最先越过哈拉山。','The Mihr Yasht, tenth hymn of the Avesta: Ahura Mazda says he made Mithra as worthy of sacrifice and prayer as himself; whoever lies to Mithra and breaks the contract brings death to the whole land; Mithra has a thousand ears and ten thousand eyes and is the first god to rise over Mount Hara, before the swift-horsed sun.','["密特拉", "契约", "阿维斯塔"]','SOURCE_BACKED','PUBLIC_CONTEXT',4,430,'依据达梅斯特泰尔译本（avesta.org）第10颂第1、2、7、13节；现代学者对诗句的理解另有讨论。','2026-10-09T00:30:00Z','2026-10-09T00:30:00Z'),
('story.zoroastrian.sixteen_lands','Sixteen good lands and their plagues — Videvdad 1','十六片良地与它们的灾祸：《万迪达德》第一章','CREATION_ACCOUNT','civ.zoroastrian','《万迪达德》第一章：阿胡拉·马兹达创造了十六片良地，第一片是善河岱提亚旁的雅利安瓦伊贾；每创造一片，“全然是死亡”的安格拉·曼纽就造出一种灾祸与之对抗——第一片是河中之蛇和寒冬，第二片是蝗虫。','Videvdad 1: Ahura Mazda makes sixteen good lands, the first being Airyana Vaejah by the good river Daitya; for each, Angra Mainyu, who is all death, counter-creates a plague — the serpent in the river and winter for the first, the locust for the second.','["安格拉·曼纽", "阿胡拉·马兹达", "创造与反创造"]','SOURCE_BACKED','PUBLIC_CONTEXT',4,435,'依据达梅斯特泰尔译本（avesta.org）第一章；译者认为这是伊朗的宗教地理，而不是迁徙记录。','2026-10-09T00:30:00Z','2026-10-09T00:30:00Z'),
('story.hawaiian.pele_journey','Pele''s journey to Halemaʻumaʻu','佩蕾的旅程：从卡希基到哈雷茂茂','MYTHIC_NARRATIVE','civ.hawaiian','美国国家公园管理局概述夏威夷口述传统：火山女神佩蕾生在遥远的卡希基，为寻找适合她的火与家人的居所，远航来到夏威夷群岛，一路向东南迁移，最后在基拉韦厄山顶的哈雷茂茂火山口安家，据说至今仍住在那里。按照夏威夷传统，经过她的土地要先请求许可。','The National Park Service summarizes Hawaiian oral history: the volcano deity Pele was born in distant Kahiki and voyaged to the Hawaiian Islands seeking a home for her fire and family, moving southeast until she settled in Halemaʻumaʻu crater at the summit of Kīlauea, where she is said still to live. In Hawaiian tradition one asks her permission to travel through her land.','["佩蕾", "火山", "旅程", "活态传统"]','SOURCE_BACKED','ATTRIBUTION_REQUIRED',4,440,'须署名的公开概述：依据美国国家公园管理局两页公开介绍；各家族与地方的 moʻolelo 版本差异很大，本站不收集。','2026-10-09T00:30:00Z','2026-10-09T00:30:00Z');

