('storyver.chinese.fuxi_xici','story.chinese.fuxi_eight_trigrams','《周易·系辞下》','Zhouyi, Xi Ci II','source.china.zhouyi_xici_xia.ctext','Xi Ci II, ch. 2','lang.lzh','中国哲学书电子化计划所收《周易·系辞下》传世本','包牺氏观象、作八卦、结网','SOURCE_BACKED','PUBLIC_CONTEXT',1,'古籍原文属公共领域；只发布篇章定位与独立白话概述。','2026-10-09T00:30:00Z'),
('storyver.chinese.zhuolu_shiji','story.chinese.huangdi_chiyou','《史记·五帝本纪》','Shiji, Annals of the Five Emperors','source.china.shiji_wudi_benji.ctext','Wu di ben ji','lang.lzh','中国哲学书电子化计划所收《史记·五帝本纪》传世本','轩辕崛起、蚩尤作乱、涿鹿之战与尊为天子','SOURCE_BACKED','PUBLIC_CONTEXT',1,'古籍原文属公共领域；只发布篇章定位与独立白话概述。','2026-10-09T00:30:00Z'),
('storyver.chinese.pangu_yiwen_leiju','story.chinese.pangu_sanwu_liji','《艺文类聚》卷一引《三五历纪》','Yiwen leiju juan 1 quoting the Sanwu liji','source.china.yiwen_leiju_juan001.wikisource','juan 1, Heaven','lang.lzh','维基文库所收《艺文类聚》卷一（据明本补）','混沌如鸡子、天地开辟与盘古日长一丈','SOURCE_BACKED','PUBLIC_CONTEXT',1,'古籍原文属公共领域；只发布篇章定位与独立白话概述。','2026-10-09T00:30:00Z'),
('storyver.chinese.nezha_xiyouji_ch4','story.chinese.nezha_wukong','《西游记》第四回','Journey to the West, chapter 4','source.china.xiyouji_ch004.wikisource','ch. 4','lang.zh','维基文库所收《西游记》第四回','天兵讨伐、三头六臂与毫毛分身','SOURCE_BACKED','PUBLIC_CONTEXT',1,'小说原文属公共领域；只发布回目定位与独立概述。','2026-10-09T00:30:00Z'),
('storyver.irish.mag_tuired_gray','story.irish.second_battle_mag_tuired','Gray 校译本（CELT T300010）','Gray edition (CELT T300010)','source.irish.cath_maige_tuired.celt','§§6–167','lang.en','科克大学 CELT 电子文本库所收 Gray 英译','四宝、鲁格入塔拉、萨温之约、布里格哀哭、巴洛尔之死与莫莉甘的宣告','SOURCE_BACKED','PUBLIC_CONTEXT',1,'Gray 译文受版权保护；只发布段落定位与独立概述。','2026-10-09T00:30:00Z'),
('storyver.slavic.kyiv_idols_pvl','story.slavic.kyiv_idols','《往年纪事》980／988 年条','Primary Chronicle, annals 980 and 988','source.slavic.pvl.obdurodon','annals 980 and 988','lang.en','Obdurodon 数字校勘版《往年纪事》','山岗神像、神名名单与 988 年毁像','SOURCE_BACKED','PUBLIC_CONTEXT',1,'只发布年条定位与独立概述。','2026-10-09T00:30:00Z'),
('storyver.zoroastrian.mihr_yasht_darmesteter','story.zoroastrian.mihr_yasht','达梅斯特泰尔英译《密赫尔颂》','Darmesteter''s Mihr Yasht','source.zoroastrian.mihr_yasht.avesta_org','Yt 10.1–13','lang.en','avesta.org 所收达梅斯特泰尔《东方圣书》译本','与阿胡拉·马兹达同受崇拜、守护契约、千耳万眼与越过哈拉山','SOURCE_BACKED','PUBLIC_CONTEXT',1,'达梅斯特泰尔 19 世纪译本属公共领域；这是活态宗教的经典，只作尊重的独立概述，不涉及仪轨。','2026-10-09T00:30:00Z'),
('storyver.zoroastrian.vd1_darmesteter','story.zoroastrian.sixteen_lands','达梅斯特泰尔英译《万迪达德》第一章','Darmesteter''s Vendidad, Fargard 1','source.zoroastrian.videvdad_1.avesta_org','Fargard 1','lang.en','avesta.org 所收达梅斯特泰尔《东方圣书》译本','十六片良地与安格拉·曼纽的反创造','SOURCE_BACKED','PUBLIC_CONTEXT',1,'达梅斯特泰尔 19 世纪译本属公共领域；这是活态宗教的经典，只作尊重的独立概述，不涉及仪轨。','2026-10-09T00:30:00Z'),
('storyver.hawaiian.pele_nps','story.hawaiian.pele_journey','美国国家公园管理局公开介绍','U.S. National Park Service public interpretation','source.hawaii.pele.nps','Pele; Holo Mai Pele','lang.en','夏威夷火山国家公园的公开解说页面','卡希基、东南方向的迁移、哈雷茂茂与请求许可','SOURCE_BACKED','ATTRIBUTION_REQUIRED',1,'须署名美国国家公园管理局；不收集 oli、mele 或非公开的家族传统。','2026-10-09T00:30:00Z'),
('storyver.maori.creation_common_threads','story.maori.creation_many','Te Ara：创世故事的共同线索','Te Ara: common threads in creation stories','source.maori.creation.teara','Page 1 — Common threads in creation stories','lang.en','Te Ara 新西兰百科中 Te Ahukaramū Charles Royal 撰写的“毛利创世传统”第1页','从黑暗到光明、天父地母的分离与自然之神','SOURCE_BACKED','ATTRIBUTION_REQUIRED',2,'须署名 Te Ahukaramū Charles Royal 与 Te Ara；只发布公开页面的独立概述，不收集具名部族版本。','2026-10-09T00:30:00Z');

INSERT OR IGNORE INTO story_sections(
    id,story_version_id,section_order,heading_zh,heading_en,body_zh,body_en,anchor_claim_id,evidence_note,uncertainty_note
) VALUES
('storysec.v0310.egyptian_heliopolis_ucl.1','storyver.egyptian.heliopolis_ucl',1,'太阳神的第一对子女','The creator''s first pair','在埃及的创世观念里，主要的创造者是太阳神，他也被称为阿图姆。他最先生出一男一女：舒和泰芙努特。学者认为“舒”这个名字和“干燥”有关，“泰芙努特”则代表湿润。','In Egyptian creation thought the principal creator is the sun-god, also called Atum. His first offshoots are a son and a daughter, Shu and Tefnet; scholars link Shu''s name to dryness and read Tefnet as moisture.','claim.v0310.egypt.shu_child_atum','UCL Digital Egypt 创世页面。','“干燥／湿润”是现代学者的词源解释。'),
('storysec.v0310.egyptian_heliopolis_ucl.2','storyver.egyptian.heliopolis_ucl',2,'大地与天空出生','Earth and sky are born','舒和泰芙努特又生下两个孩子：大地之神盖布和天空女神努特。干燥与湿润，变成了坚实的大地和古埃及人眼中充满水的天空。','Shu and Tefnet in turn produce two children: Geb, god of the earth, and Nut, goddess of the sky — dryness and moisture crystallised into solid earth and a sky the Egyptians thought of as watery.','claim.v0310.egypt.geb_child_shu','同一页面的子女段落。',NULL),
('storysec.v0310.egyptian_heliopolis_ucl.3','storyver.egyptian.heliopolis_ucl',3,'舒把天地分开','Shu holds earth and sky apart','盖布和努特被舒分开，天在上、地在下。零散的古代记载暗示，这种分离必须被强制维持，否则天地还会继续生出神来。','Shu separates Geb and Nut, sky above and earth below. Scattered references suggest the separation had to be enforced, or earth and sky would keep producing divine offspring.','claim.v0310.egypt.shu_separation','UCL 页面关于天地分离的说明。','这是学者对零散材料的归纳，不是单一文本的原话。'),
('storysec.v0310.egyptian_heliopolis_ucl.4','storyver.egyptian.heliopolis_ucl',4,'塞特、奥西里斯与伊西斯','Seth, Osiris and Isis','后来，奥西里斯“无序的兄弟”塞特出于嫉妒杀害了他，把遗体分开，并取代他成为世界之王。伊西斯找回奥西里斯的肢体，让遗体恢复到足以受孕，生下了荷鲁斯。','Later Osiris''s anarchic brother Seth, out of jealousy, murders him, dismembers him and takes his place as king of the world. Isis collects the limbs and revives the body enough to conceive a child, Horus.','claim.v0310.egypt.seth_kills_osiris','UCL 页面的奥西里斯故事概述。','古代文献中这个故事有许多版本；本站不合成“标准版”。'),
('storysec.v0310.egyptian_heavenly_cow_ucl.1','storyver.egyptian.heavenly_cow_ucl',1,'人类反叛拉','Humankind rebels against Ra','一部新王国时期的宗教文献记载：人们起来反叛太阳神拉。拉决定惩罚他们，后来他也离开人间，退到天上。','A New Kingdom religious composition records that people rebel against the sun-god Ra. He resolves to punish them, and in the end he withdraws to the sky.','claim.v0310.egypt.ra_rebellion','UCL 页面对《天牛之书》的概述。',NULL),
('storysec.v0310.egyptian_heavenly_cow_ucl.2','storyver.egyptian.heavenly_cow_ucl',2,'眼睛化作塞赫麦特','The Eye becomes Sekhmet','拉把自己的眼睛从身体里派出去，成为一个独立的“女儿”。她化作塞赫麦特——意思是“强大的女神”——几乎把人类全部消灭。','Ra sends his Eye out from his body as a separate offshoot, a ''daughter''. As Sekhmet, ''the mighty goddess'', she almost annihilates humankind.','claim.v0310.egypt.sekhmet_eye_of_ra','同一概述的“拉的眼睛”段落。','“强大的女神”是 UCL 给出的释义。'),
('storysec.v0310.egyptian_heavenly_cow_ucl.3','storyver.egyptian.heavenly_cow_ucl',3,'一湖红色的啤酒','A lake of red beer','众神用计：他们把一湖啤酒染成红色，看起来像人血。她喝下后醉得香甜，脾气也软化下来，重新变回慈爱、温柔的哈托尔。','The gods play a trick: they colour a lake of beer red to look like human blood. She drinks, becomes sweetly drunk, and reverts to her loving, maternal character as Hathor.','claim.v0310.egypt.sekhmet_to_hathor','同一概述的结尾。','这是故事中的性格转变；数据库不把两位女神合并为同一实体。'),
('storysec.v0310.egyptian_weighing_ani_bm.1','storyver.egyptian.weighing_ani_bm',1,'心脏与羽毛','A heart and a feather','画面中央是一座天平。左边的秤盘里放着阿尼的心脏，右边是一根羽毛，代表真理与秩序女神玛阿特。','At the centre stands a balance. In the left pan lies Ani''s heart; in the right, a feather representing Maat, goddess of truth and order.','claim.v0310.egypt.ani_depicts_weighing','大英博物馆 EA10470,3 藏品描述。',NULL),
('storysec.v0310.egyptian_weighing_ani_bm.2','storyver.egyptian.weighing_ani_bm',2,'阿努比斯扶稳天平','Anubis steadies the balance','胡狼头的阿努比斯跪在天平旁，拉着右边秤盘的绳子，扶稳天平的铅锤。博物馆的说明称他是“在防腐之所的那一位”。','Jackal-headed Anubis kneels by the balance, holding the cord of the right-hand pan and steadying its plumb bob. The museum describes him as ''he who is in the place of embalming''.','claim.v0310.egypt.anubis_weighing','同一藏品描述中关于阿努比斯的部分。',NULL),
('storysec.v0310.egyptian_weighing_ani_bm.3','storyver.egyptian.weighing_ani_bm',3,'托特准备记录','Thoth stands ready to record','托特在画中出现两次：一只小狒狒坐在天平顶端；右边站着朱鹭头的“众神书吏”，手持调色板和芦苇笔，准备记下审问的结果。','Thoth appears twice: as a small baboon sitting on top of the balance, and as the ibis-headed scribe of the gods standing to the right with palette and reed, ready to write down the result.','claim.v0310.egypt.thoth_weighing','同一藏品描述中关于托特的部分。','称量的最终结果和吞噬心脏的怪兽不在这条博物馆描述里，本站不补写。'),
('storysec.v0310.egyptian_mourning_sisters_met.1','storyver.egyptian.mourning_sisters_met',1,'举手掩面的奈芙蒂斯','Nephthys raises her hand','这尊小木像跪在地上，一只手举到脸前，是古埃及的哀悼姿势。她头上的象形文字符号，表明她就是女神奈芙蒂斯。','The small wooden figure kneels and raises one hand before her face, an Egyptian gesture of mourning. The hieroglyph on her head identifies her as the goddess Nephthys.','claim.v0310.egypt.nephthys_figure','大都会艺术博物馆 12.182.23a。',NULL),
('storysec.v0310.egyptian_mourning_sisters_met.2','storyver.egyptian.mourning_sisters_met',2,'和伊西斯成对','A pair with Isis','博物馆说明，这尊像和另一尊伊西斯像（12.182.23b）是一对，两位女神以同样的姿势哀悼。','The museum states that the figure forms a pair with a figure of Isis (12.182.23b), the two goddesses mourning in the same posture.','claim.v0310.egypt.mourners_pair','两件藏品的说明互相引用。',NULL),
('storysec.v0310.egyptian_mourning_sisters_met.3','storyver.egyptian.mourning_sisters_met',3,'守在奥西里斯身旁','Beside the body of Osiris','在古埃及图像中，这两位哀悼女神陪伴在奥西里斯的遗体旁，一左一右。博物馆推测，这对木像原本可能放在死者棺椁的两端。','In Egyptian representations the two mourning goddesses accompany the body of Osiris, one at each end. The museum suggests these figures were presumably placed at either end of the deceased''s sarcophagus.','claim.v0310.egypt.nephthys_mourns_osiris','大都会艺术博物馆藏品说明。','“放在棺椁两端”是博物馆的推测，不是出土记录。'),
('storysec.v0310.japanese_izanagi_izanami_kojiki.1','storyver.japanese.izanagi_izanami_kojiki',1,'天浮桥上的长矛','A spear from the Floating Bridge','天上的众神命令伊邪那岐和伊邪那美去巩固还在漂浮的大地，并交给他们一支镶玉的天沼矛。两神站在天浮桥上，把矛伸进海里搅动；提起矛时，矛尖滴下的盐水层层堆积，成了淤能碁吕岛。','The heavenly deities command Izanagi and Izanami to make firm the drifting land and give them a jewelled spear. Standing on the Floating Bridge of Heaven, they stir the brine; when they lift the spear, the drops from its tip pile up into Onogoro Island.','claim.v0310.japan.onogoro_result','张伯伦译本第三节（kj010）。','《日本书纪》说两神是自己决定动手，本版不合并。'),
('storysec.v0310.japanese_izanagi_izanami_kojiki.2','storyver.japanese.izanagi_izanami_kojiki',2,'火神出生','The birth of the fire deity','两神结合，生出许多岛屿和神灵。可是伊邪那美生下火神时被烧伤，病倒在床，最终“神去”——也就是死去。','Joined together, the pair bring forth islands and deities. But when Izanami gives birth to the Deity-of-Fire she is burned, falls sick, and at length ''divinely retires'' — she dies.','claim.v0310.japan.izanami_death','张伯伦译本第七节（kj014）。',NULL),
('storysec.v0310.japanese_izanagi_izanami_kojiki.3','storyver.japanese.izanagi_izanami_kojiki',3,'追到黄泉','Following her to Yomi','伊邪那岐想再见到妻子，便追到黄泉，请她回去：“我们造的国土还没有完成。”伊邪那美回答：你来得太晚了，我已经吃了黄泉灶火煮的东西——不过她答应去和黄泉的神商量。','Longing to see her, Izanagi follows Izanami to Yomi and asks her to come back, for the lands they made are not yet finished. She answers that he has come too late: she has already eaten from the hearth of Yomi — yet she agrees to consult the deities there.','claim.v0310.japan.izanagi_yomi','张伯伦译本第九节（kj016）。','之后的逃离情节可参看本库“黄泉中的八雷神”故事。'),
('storysec.v0310.japanese_izanagi_izanami_kojiki.4','storyver.japanese.izanagi_izanami_kojiki',4,'洗出三位贵神','Three deities born of washing','伊邪那岐回来后在水中洗净自己，身上不断化生出神。最后，他洗左眼时生出天照大神，洗右眼时生出月读，洗鼻子时生出须佐之男。','Back from Yomi, Izanagi bathes to purify himself, and deities are born as he washes. Last of all, washing his left eye brings forth Amaterasu, his right eye Tsukuyomi, and his nose Susanoo.','claim.v0310.japan.tsukuyomi_born','张伯伦译本第十节（kj017）及译注。','三神的通行名称来自译者注释。'),
('storysec.v0310.norse_vanir_gylf.1','storyver.norse.vanir_gylf',1,'海风之神尼奥尔德','Njörðr of wind and sea','尼奥尔德住在天上一个叫诺欧通的地方。他掌管风的运行，能平息海浪和火焰；出海航行和捕鱼的人都向他祈祷。他在华纳海姆长大，后来作为人质被送到阿萨神族。','Njörðr lives in heaven at a place called Nóatún. He rules the motion of the wind and can calm sea and fire; those who sail or fish pray to him. He was raised in Vanaheim and later given to the Æsir as a hostage.','claim.v0310.norse.njord_wind_sea','《欺骗古鲁菲》第23章。',NULL),
('storysec.v0310.norse_vanir_gylf.2','storyver.norse.vanir_gylf',2,'弗雷与芙蕾雅','Freyr and Freyja','尼奥尔德有一儿一女。儿子弗雷掌管雨水、阳光和大地的收成，人们向他祈求丰年与富足。女儿芙蕾雅住在弗尔克范格，每当她骑马出战，就分得一半战死者，另一半归奥丁；她乘坐的车由两只猫拉着。','Njörðr has a son and a daughter. Freyr rules rain, sunshine and the produce of the earth, and people pray to him for good seasons and wealth. Freyja lives at Fólkvangr; whenever she rides to battle she takes half the slain, Odin the other half, and her chariot is drawn by two cats.','claim.v0310.norse.freyja_slain','《欺骗古鲁菲》第24章。',NULL),
('storysec.v0310.norse_vanir_gylf.3','storyver.norse.vanir_gylf',3,'弗雷交出宝剑','Freyr gives away his sword','后来，弗雷爱上了巨人之女葛德。为了娶到她，他把自己的宝剑交给了别人作为代价——这把剑从此不在他手中。','Later Freyr falls in love with Gerðr, a giant''s daughter. To win her he gives away his sword as the price, and the sword is no longer his.','claim.v0310.norse.freyr_sword','《欺骗古鲁菲》第37章。','葛德尚未单独建立实体；诸神黄昏中的后果另行登记。'),
('storysec.v0310.norse_tyr_gylf.1','storyver.norse.tyr_gylf',1,'最勇敢的神','The boldest god','斯诺里说，提尔是众神中最勇敢、最无畏的一位，打仗时人们向他祈求胜利。他只有一只手。','Snorri says Týr is the boldest and most valiant of the gods, invoked for victory in battle — and he has only one hand.','claim.v0310.norse.tyr_brave','《欺骗古鲁菲》第25章。',NULL),
('storysec.v0310.norse_tyr_gylf.2','storyver.norse.tyr_gylf',2,'一只手作担保','A hand as a pledge','众神想用一条魔法绳索捆住狼芬里尔。狼起了疑心，要求有人把手放进它嘴里，保证这不是诡计。众神面面相觑，只有提尔伸出了右手。','The gods mean to bind the wolf Fenrir with a magic fetter. Suspicious, the wolf demands that someone put a hand in its mouth as a pledge of good faith. Only Týr holds out his right hand.','claim.v0310.norse.tyr_fenrir','《欺骗古鲁菲》第34章。',NULL),
('storysec.v0310.norse_tyr_gylf.3','storyver.norse.tyr_gylf',3,'狼咬断了手','The wolf bites','绳索越挣越紧，狼发现自己被骗了，便咬断了提尔的手。众神都笑了，只有提尔没有笑。','The more the wolf struggles, the tighter the fetter grows. Realizing it has been tricked, Fenrir bites off Týr''s hand — and all the gods laugh, except Týr.','claim.v0310.norse.fenrir_bound','《欺骗古鲁菲》第34章。',NULL),
('storysec.v0310.norse_heimdall_gylf.1','storyver.norse.heimdall_gylf',1,'桥头的守望者','Watchman at the bridge','海姆达尔是众神的守望者。他住在彩虹桥边一个叫希敏约格的地方，在天的尽头守着桥，防止山巨人闯进来。','Heimdallr is the watchman of the gods. He lives at Himinbjörg by Bifröst, at the edge of heaven, guarding the bridge against the mountain-giants.','claim.v0310.norse.heimdall_watchman','《欺骗古鲁菲》第27章。',NULL),
('storysec.v0310.norse_heimdall_gylf.2','storyver.norse.heimdall_gylf',2,'看得远，听得清','Keen eyes and ears','他需要的睡眠比鸟还少，无论白天黑夜都能看见一百里远；他还能听见草在地上生长、羊毛在羊身上生长的声音。','He needs less sleep than a bird and sees a hundred leagues by day or night; he can hear grass growing in the ground and wool growing on sheep.','claim.v0310.norse.heimdall_senses','《欺骗古鲁菲》第27章。',NULL),
('storysec.v0310.norse_heimdall_gylf.3','storyver.norse.heimdall_gylf',3,'加拉尔号角与九位母亲','Gjallarhorn and nine mothers','海姆达尔有一支号角，叫加拉尔号角，吹响时所有世界都能听见。斯诺里还说，他是九位母亲的儿子，而这九位母亲是姐妹。','Heimdallr has a horn called Gjallarhorn, whose blast is heard in all worlds. Snorri also says he is the son of nine mothers, who were sisters.','claim.v0310.norse.heimdall_horn','《欺骗古鲁菲》第27章。','九位母亲的名字见其他诗篇，本版不列出。'),
('storysec.v0310.norse_ymir_gylf.1','storyver.norse.ymir_gylf',1,'冰与火之间','Between ice and fire','世界还不存在时，只有一道叫金伦加的深渊。北方的寒霜与南方的热气在这里相遇，融化的水滴里生出了巨人尤弥尔。','Before the world exists there is only the void of Ginnungagap. Where rime from the north meets heat from the south, the thawing drops bring forth the giant Ymir.','claim.v0310.norse.ymir_origin','《欺骗古鲁菲》第5章。',NULL),
('storysec.v0310.norse_ymir_gylf.2','storyver.norse.ymir_gylf',2,'奥丁兄弟杀死尤弥尔','Odin and his brothers kill Ymir','布尔的儿子们——奥丁、维利和维——杀死了巨人尤弥尔。','The sons of Borr — Odin, Vili and Vé — kill the giant Ymir.','claim.v0310.norse.odin_kills_ymir','《欺骗古鲁菲》第7章。',NULL),
('storysec.v0310.norse_ymir_gylf.3','storyver.norse.ymir_gylf',3,'用身体造世界','A world made from a body','他们用尤弥尔的身体造出世界：肉变成大地，血变成海洋和湖泊，骨头变成山岩，头骨被举起来成为天空。','From Ymir''s body they make the world: his flesh becomes the earth, his blood the sea and lakes, his bones the rocks, and his skull is raised up as the sky.','claim.v0310.norse.ymir_world','《欺骗古鲁菲》第8章。','斯诺里的散文综述与诗歌见证可能有细节差异。'),
('storysec.v0310.norse_frigg_gylf.1','storyver.norse.frigg_gylf',1,'知晓命运的女神','The goddess who knows all fates','弗丽嘉是奥丁的妻子。斯诺里说，她知道一切人的命运，只是从不说出来。','Frigg is Odin''s wife. Snorri says she knows the fates of all, though she does not speak them aloud.','claim.v0310.norse.frigg_wife','《欺骗古鲁菲》第20章。',NULL),
('storysec.v0310.norse_frigg_gylf.2','storyver.norse.frigg_gylf',2,'万物发誓','Everything swears','巴德尔做了不祥的梦。弗丽嘉便去找火、水、铁和各种金属、石头、土地、树木、疾病、野兽、鸟和蛇，让它们都发誓不伤害巴德尔。只有长在英灵殿西边的一株小槲寄生，她觉得太小，没有让它发誓。','Baldr has ominous dreams, so Frigg makes fire, water, iron and all metals, stones, earth, trees, sicknesses, beasts, birds and serpents swear not to harm him. Only a young mistletoe shoot she thinks too small to ask.','claim.v0310.norse.frigg_oaths','《欺骗古鲁菲》第49章。',NULL),
('storysec.v0310.norse_frigg_gylf.3','storyver.norse.frigg_gylf',3,'槲寄生','The mistletoe','众神以为巴德尔刀枪不入，便拿东西扔他取乐。然而那株没有发誓的槲寄生被做成了投枪，巴德尔被它刺中而死。','Believing Baldr unharmable, the gods amuse themselves by throwing things at him. But the mistletoe that never swore is made into a dart, and Baldr is struck down and dies.','claim.v0310.norse.baldr_death','《欺骗古鲁菲》第49章。','投掷者与幕后之人的情节将在后续批次逐段登记。'),
('storysec.v0310.mexica_coatepec_fc.1','storyver.mexica.coatepec_fc',1,'一团羽毛','A ball of feathers','科阿特利库埃住在蛇山上。一天她打扫时，一团羽毛从天上飘下来。她把羽毛捡起来，塞在腰间——就这样怀孕了。','Coatlicue lives on Coatepec. One day as she sweeps, a ball of feathers drifts down. She picks it up and tucks it at her waist — and so she becomes pregnant.','claim.v0310.mexica.coatlicue_feathers','《佛罗伦萨手抄本》第三卷第1章。',NULL),
('storysec.v0310.mexica_coatepec_fc.2','storyver.mexica.coatepec_fc',2,'兄妹要杀母亲','Her children turn against her','她的女儿科约尔沙乌基对兄弟们——四百个南方人——说：母亲让我们蒙羞，我们必须杀了她。于是他们全副武装，朝蛇山进发。','Her daughter Coyolxauhqui tells her brothers, the four hundred Centzon Huitznahua, that their mother has shamed them and must be killed. Armed, they set out for Coatepec.','claim.v0310.mexica.coyol_event','《佛罗伦萨手抄本》第三卷第1章。',NULL),
('storysec.v0310.mexica_coatepec_fc.3','storyver.mexica.coatepec_fc',3,'全副武装地出生','Born fully armed','腹中的维齐洛波奇特利安慰母亲：不要怕，我知道该怎么做。敌人冲上山顶的那一刻，他出生了，手持盾牌、投枪和投枪器。','From the womb Huitzilopochtli comforts his mother: do not be afraid, I know what to do. The moment the attackers reach the summit he is born, carrying shield, darts and dart-thrower.','claim.v0310.mexica.huitz_armed','《佛罗伦萨手抄本》第三卷第1章。',NULL),
('storysec.v0310.mexica_coatepec_fc.4','storyver.mexica.coatepec_fc',4,'山顶的胜利','Victory on the summit','维齐洛波奇特利砍下科约尔沙乌基的头，她的身体沿着蛇山滚落下去。四百个兄弟也被他从山顶追得四散奔逃。','Huitzilopochtli cuts off Coyolxauhqui''s head, and her body tumbles down the side of Coatepec. He drives the four hundred brothers from the summit, scattering them in every direction.','claim.v0310.mexica.huitz_kills_coyol','《佛罗伦萨手抄本》第三卷第1章。','学者认为这段叙事与大神庙的布局相呼应，属于解释，不写成事实。'),
('storysec.v0310.mexica_tollan_fc.1','storyver.mexica.tollan_fc',1,'被当作神的蒂特拉卡瓦','Titlacauan, held to be a god','第三卷第2章讲人们怎样把一位叫蒂特拉卡瓦、也叫特斯卡特利波卡的人物当作神来敬奉。','Chapter 2 of Book 3 tells how one called Titlacauan, or Tezcatlipoca, came to be regarded as a god.','claim.v0310.mexica.tezca_titlacauan','《佛罗伦萨手抄本》第三卷第2章。',NULL),
('storysec.v0310.mexica_tollan_fc.2','storyver.mexica.tollan_fc',2,'图拉的大法师','The great wizard of Tollan','第3章讲羽蛇神——图拉的一位大法师。第4章说，当巫师们来到他身边，他的荣光便走到了尽头；第5章又记下蒂特拉卡瓦带来的另一个异兆。','Chapter 3 tells of Quetzalcoatl, a great wizard at Tollan. Chapter 4 relates how his glory came to an end when the sorcerers came to him, and chapter 5 records another portent brought about by Titlacauan.','claim.v0310.mexica.quetzal_event','《佛罗伦萨手抄本》第三卷第3–5章。','本段依据章节标题与概要，具体情节尚未逐句核对。'),
('storysec.v0310.mexica_tollan_fc.3','storyver.mexica.tollan_fc',3,'雪山之间','Between the snow mountains','第14章记载，羽蛇神离去时，追随他的人经过伊斯塔克特佩特尔与波波卡特佩特尔两座雪山之间，被冻死在冰雪里。','Chapter 14 records that as Quetzalcoatl departs, his vassals freeze to death in the ice as they pass between Iztactepetl and Popocatepetl.','claim.v0310.mexica.vassals_froze','《佛罗伦萨手抄本》第三卷第14章。',NULL),
('storysec.v0310.mexica_templo_mayor_inah.1','storyver.mexica.templo_mayor_inah',1,'南边的战神','The war god on the south','大神庙南侧的神殿属于维齐洛波奇特利——墨西加人的太阳战神，也是他们的守护神。','The southern chapel of the Templo Mayor belongs to Huitzilopochtli, the Mexica''s solar god of war and their patron.','claim.v0310.mexica.huitz_templo','INAH 大神庙遗址博物馆说明。',NULL),
('storysec.v0310.mexica_templo_mayor_inah.2','storyver.mexica.templo_mayor_inah',2,'北边的雨神','The rain god on the north','北侧的神殿属于特拉洛克——掌管雨水、与农业紧密相连的神。战争与农业，两位神并立在同一座金字塔的顶端。','The northern temple belongs to Tlaloc, god of rain and closely tied to agriculture. War and farming stand side by side at the top of one pyramid.','claim.v0310.mexica.tlaloc_templo','INAH 大神庙遗址博物馆说明。',NULL),
('storysec.v0310.mexica_templo_mayor_inah.3','storyver.mexica.templo_mayor_inah',3,'一层层长高的神庙','A temple that grew in layers','据 INAH 介绍，墨西加人在1325年建立特诺奇蒂特兰时修了一座小神庙，此后经过多次重建和扩建，越修越高。','According to INAH, the Mexica built a small temple when they founded Tenochtitlan in 1325, and it was rebuilt and enlarged many times over.','claim.v0310.mexica.templo_layers','INAH 大神庙遗址博物馆说明。','各建造阶段的具体年代仍有不确定之处。'),
('storysec.v0310.maya_kukulkan_unesco.1','storyver.maya.kukulkan_unesco',1,'奇琴伊察的金字塔','A pyramid at Chichen-Itza','奇琴伊察是尤卡坦半岛上的前西班牙时期古城，已列入世界遗产名录。联合国教科文组织的记录把卡斯蒂略金字塔列为城市北部建筑群中的主要建筑。','Chichen-Itza is a pre-Hispanic city on the Yucatán peninsula, inscribed on the World Heritage List. UNESCO''s record names El Castillo among the chief buildings of the city''s northern group.','claim.v0310.maya.castillo_part','联合国教科文组织世界遗产 483 号记录。',NULL),
('storysec.v0310.maya_kukulkan_unesco.2','storyver.maya.kukulkan_unesco',2,'库库尔坎神庙','The Temple of Kukulkan','奇琴伊察北区最重要的建筑是卡斯蒂略金字塔，联合国教科文组织的记录说，它又被称为“库库尔坎神庙”。','The chief monument of Chichen-Itza''s northern group is El Castillo, which UNESCO''s record says is also known as the Temple of Kukulkan.','claim.v0310.maya.castillo_kukulkan','联合国教科文组织世界遗产 483 号记录。',NULL),
('storysec.v0310.maya_kukulkan_unesco.3','storyver.maya.kukulkan_unesco',3,'一个名字的翻译','A name in translation','同一记录提到一种最常见的说法：图拉之王“一芦苇·托皮尔钦·羽蛇”占领了这座城市，而“库库尔坎”正是玛雅人对“羽蛇”这个名字的翻译。','The same record cites the most common version: the King of Tula, Ce Acatl Topiltzin Quetzalcoatl, took the city — and ''Kukulkan'' is how the Maya translated his name.','claim.v0310.maya.kukulkan_name','联合国教科文组织世界遗产 483 号记录。','这是关于统治者名号的传统说法，不把玛雅与墨西加的神合并为同一实体。'),
('storysec.v0310.maya_chahk_met.1','storyver.maya.chahk_met',1,'水中的雨神','The rain god in the water','这只古典期的玛雅陶盘上，雨神恰克半身浸在水波纹里，四周写着表示“海”的象形文字。','On this Classic Maya plate the rain god Chahk stands waist-deep in watery motifs, surrounded by hieroglyphs for ''sea''.','claim.v0310.maya.chahk_plate','大都会艺术博物馆 2021.320 号。',NULL),
('storysec.v0310.maya_chahk_met.2','storyver.maya.chahk_met',2,'Chahk 这个名字','The name Chahk','在古典期的玛雅象形文字里，这位雨神的名字写作 Chahk；人们常写的“恰克”就是这个名字。','In Classic-period Maya hieroglyphs the rain god''s name is written Chahk — the familiar ''Chaac''.','claim.v0310.maya.chahk_name','大都会艺术博物馆藏品说明。',NULL),
('storysec.v0310.maya_chahk_met.3','storyver.maya.chahk_met',3,'进入博物馆','Into the museum','这只陶盘在 2021 年由 Mol 收藏捐赠给大都会艺术博物馆。博物馆的说明只描述画面本身，并没有讲述一个完整的雨神故事。','The plate entered The Metropolitan Museum of Art in 2021 as a gift of the Mol Collection. The museum''s entry describes the image itself; it does not narrate a full rain-god myth.','claim.v0310.maya.chahk_held_met','大都会艺术博物馆藏品出处说明。','这是物质见证，本站不补写神话情节。'),
('storysec.v0310.maya_itzamnaaj_met.1','storyver.maya.itzamnaaj_met',1,'年老的天神','The aged god','2022 年的展览按“众神的一生”展开：从婴儿、壮年到老年。其中的老年之神叫伊察姆纳（Itzamnaaj），他还有一个鸟形化身，两者在太初神话中都很重要。','The 2022 exhibition followed the gods through life — infancy, prime and old age. The aged god is Itzamnaaj, who has a bird avatar; both play important roles in primordial myths.','claim.v0310.maya.itzamnaaj_aged','大都会艺术博物馆 2022 年展览说明。',NULL),
('storysec.v0310.maya_itzamnaaj_met.2','storyver.maya.itzamnaaj_met',2,'名字仍有疑问','A name still in question','“Itzamnaaj”是殖民时期尤卡坦一位重要神祇的名字。博物馆提醒，古典期这位老神的名字符号该怎样读，学界还没有定论。','''Itzamnaaj'' is the name of a major deity in colonial Yucatán. The museum notes that how to read the Classic-period name glyph of this elderly god is still uncertain.','claim.v0310.maya.itzamnaaj_name','大都会艺术博物馆展览说明。','名字读法未定，本站同时保留“伊察姆纳”与“Itzamnaaj”。'),
('storysec.v0310.maya_itzamnaaj_met.3','storyver.maya.itzamnaaj_met',3,'故事还要等更多见证','The story awaits more witnesses','这里依据的是一份现代展览介绍，而不是古代文本。展览说伊察姆纳在太初神话中很重要，但没有在说明里讲出那些神话；本站因此不替它补写情节。','This version rests on a modern exhibition text, not an ancient one. The exhibition says Itzamnaaj mattered in primordial myths but does not retell them, so the site does not fill in a plot.','claim.v0310.maya.itzamnaaj_scope','大都会艺术博物馆展览说明。','待找到可定位的古代或殖民时期文本见证后再扩充。'),
('storysec.v0310.sumerian_enki_ninhursag_etcsl.1','storyver.sumerian.enki_ninhursag_etcsl',1,'纯净的迪尔蒙','Pure Dilmun','故事开头描写迪尔蒙：一片纯净、安宁的土地，一切都还处在最初的状态。','The composition opens with Dilmun, a pure and peaceful land where everything is still in its first state.','claim.v0310.sumer.dilmun_setting','ETCSL 1.1.1 开篇。','神话中的迪尔蒙不等同于历史上的同名地区。'),
('storysec.v0310.sumerian_enki_ninhursag_etcsl.2','storyver.sumerian.enki_ninhursag_etcsl',2,'吃下植物，招来诅咒','Eating the plants brings a curse','恩基把那里长出的植物一一吃掉。宁胡尔萨格大怒，诅咒他，恩基于是病倒了。','Enki eats the plants that have grown there, one after another. Ninhursaĝa, enraged, curses him, and he falls ill.','claim.v0310.sumer.ninhursag_curse','ETCSL 1.1.1 植物与诅咒段落。','具体植物名单尚未逐项建模。'),
('storysec.v0310.sumerian_enki_ninhursag_etcsl.3','storyver.sumerian.enki_ninhursag_etcsl',3,'为每一处病痛生出神','A deity for every ailment','后来宁胡尔萨格回到恩基身边。他哪里疼，她就为那里生出一位神灵，就这样把他治好了。','Later Ninhursaĝa returns to Enki. For each part of his body that aches, she brings forth a deity, and so he is healed.','claim.v0310.sumer.ninhursag_heals','ETCSL 1.1.1 疗愈段落。',NULL),
('storysec.v0310.sumerian_nanna_journey_etcsl.1','storyver.sumerian.nanna_journey_etcsl',1,'想念父亲的城市','Longing for his father''s city','英勇的南纳一心想着父亲的城市——尼普尔。','Heroic Nanna-Suen sets his mind on his father''s city, Nibru.','claim.v0310.sumer.nanna_child_enlil','ETCSL 1.5.1 开篇。',NULL),
('storysec.v0310.sumerian_nanna_journey_etcsl.2','storyver.sumerian.nanna_journey_etcsl',2,'满船的礼物','A boat full of gifts','他准备了一条船，装满各种礼物，顺着河道一路航行，前往尼普尔。','He prepares a boat, loads it with gifts and sails along the waterways toward Nibru.','claim.v0310.sumer.nanna_journey','ETCSL 1.5.1。','沿途停靠的城市尚未逐项登记。'),
('storysec.v0310.sumerian_nanna_journey_etcsl.3','storyver.sumerian.nanna_journey_etcsl',3,'带回乌尔的祝福','Blessings for Urim','恩利尔欢迎儿子的到来，赐给他丰饶的物产，让他带回自己的城市乌尔。','Enlil welcomes his son and grants him abundance to take back to his own city, Urim.','claim.v0310.sumer.enlil_blesses','ETCSL 1.5.1 结尾。','学者把这首诗与城市间运送供品的仪式相联系，属于解释层。'),
('storysec.v0310.sumerian_gilgamesh_huwawa_etcsl.1','storyver.sumerian.gilgamesh_huwawa_etcsl',1,'要进山去','To the mountains','吉尔伽美什决定动身进山。','Gilgameš resolves to set off for the mountains.','claim.v0310.sumer.gilgamesh_event','ETCSL 1.8.1.5 开篇。',NULL),
('storysec.v0310.sumerian_gilgamesh_huwawa_etcsl.2','storyver.sumerian.gilgamesh_huwawa_etcsl',2,'先告诉乌图','First tell Utu','恩奇都说：山是乌图管的，这件事应该先让乌图知道。','Enkidu says the mountains are Utu''s concern, so Utu should be told of the plan.','claim.v0310.sumer.utu_told','ETCSL 1.8.1.5 开篇。',NULL),
('storysec.v0310.sumerian_gilgamesh_huwawa_etcsl.3','storyver.sumerian.gilgamesh_huwawa_etcsl',3,'眼泪换来的向导','Guides granted for tears','吉尔伽美什向乌图祈求。乌图接受他的眼泪作为礼物，赐给他七位勇士为他引路，一同去面对胡瓦瓦。','Gilgameš prays to Utu, who accepts his tears as a gift and grants him seven warriors to guide him toward Ḫuwawa.','claim.v0310.sumer.utu_helps','ETCSL 1.8.1.5 乌图赐助段落。','七位勇士的具体身份描述尚未逐句建模。'),
('storysec.v0310.chinese_fuxi_xici.1','storyver.chinese.fuxi_xici',1,'包牺氏治理天下','When Baoxi ruled the world','《系辞下》讲古代圣人的发明，第一位就是包牺氏——后世通常写作伏羲。书里说，远古的时候，是他在治理天下。','Xi Ci II lists the inventions of the ancient sages, and the first is Baoxi — usually written Fuxi in later texts. In remote antiquity, it says, he ruled all under heaven.','claim.v0310.china.fuxi_baoxi','《系辞下》第二章开头。','“包牺”即“伏羲”是传统注疏的读法。'),
('storysec.v0310.chinese_fuxi_xici.2','storyver.chinese.fuxi_xici',2,'仰观天，俯察地','Looking up, looking down','他抬头观察天上的日月星辰，低头观察大地的形势；又细看鸟兽身上的花纹，看各地适合生长什么。近处，他从自己的身体取法；远处，他从万物取法。','He looked up at the images in the sky and down at the patterns of the earth; he studied the markings of birds and beasts and what each land was suited for. Near at hand he drew on his own body, and far off on all things.','claim.v0310.china.fuxi_observes','《系辞下》第二章。',NULL),
('storysec.v0310.chinese_fuxi_xici.3','storyver.chinese.fuxi_xici',3,'画出八卦','The first eight trigrams','于是他开始画出八卦——八个由三条线组成的符号，用来通达神明的德性，把万物的情状分门别类。','Thereupon he first made the eight trigrams — eight figures of three lines each — to communicate with spirit-like virtue and to sort the dispositions of the myriad things.','claim.v0310.china.fuxi_bagua','《系辞下》第二章“于是始作八卦”。',NULL),
('storysec.v0310.chinese_fuxi_xici.4','storyver.chinese.fuxi_xici',4,'结绳为网','Cords become nets','他还把绳子打结，做成罗网，人们用它打猎、捕鱼。《系辞》接下来再讲神农等后来的圣人，这里只讲伏羲这一段。','He also knotted cords into nets, which people used to hunt and fish. The Xi Ci then moves on to later sages such as Shennong; this retelling covers only Baoxi''s part.','claim.v0310.china.fuxi_nets','《系辞下》第二章“作结绳而为罔罟”。','后续圣人的发明不在本故事范围内。'),
('storysec.v0310.chinese_zhuolu_shiji.1','storyver.chinese.zhuolu_shiji',1,'神农氏衰落','Shennong''s line declines','黄帝是少典的儿子，姓公孙，名轩辕。他那个时代，神农氏的统治衰落了，诸侯互相攻打、欺压百姓，神农氏却无力征讨。轩辕于是操练军队，去讨伐不肯朝贡的诸侯。','The Yellow Emperor was the son of Shaodian, surnamed Gongsun and named Xuanyuan. In his time the rule of Shennong had declined; the lords attacked one another and oppressed the people, and Shennong could not punish them. So Xuanyuan trained troops to subdue the lords who would not pay tribute.','claim.v0310.china.huangdi_identity','《五帝本纪》开篇。','此前轩辕与炎帝在阪泉的三次交战本故事未展开。'),
('storysec.v0310.chinese_zhuolu_shiji.2','storyver.chinese.zhuolu_shiji',2,'蚩尤作乱','Chiyou rebels','诸侯之中，蚩尤最为凶暴，没有人能制服他。蚩尤起来作乱，不听从帝王的命令。','Among the lords Chiyou was the most violent, and no one could subdue him. Chiyou rose in rebellion and would not obey the ruler''s command.','claim.v0310.china.chiyou_rebels','《五帝本纪》“蚩尤作乱，不用帝命”。',NULL),
('storysec.v0310.chinese_zhuolu_shiji.3','storyver.chinese.zhuolu_shiji',3,'涿鹿之野','In the wilds of Zhuolu','轩辕征召各路诸侯的军队，在涿鹿的原野上与蚩尤交战，终于把蚩尤擒住并杀死。','Xuanyuan called up the armies of the lords and fought Chiyou in the wilds of Zhuolu, and at last captured and killed him.','claim.v0310.china.huangdi_kills_chiyou','《五帝本纪》“遂禽杀蚩尤”。','涿鹿不在本站映射为现代坐标。'),
('storysec.v0310.chinese_zhuolu_shiji.4','storyver.chinese.zhuolu_shiji',4,'尊为天子','Honoured as Son of Heaven','诸侯们都尊奉轩辕为天子，取代了神农氏，这就是黄帝。','The lords all honoured Xuanyuan as Son of Heaven in place of Shennong: this was the Yellow Emperor.','claim.v0310.china.huangdi_son_of_heaven','《五帝本纪》“诸侯咸尊轩辕为天子”。',NULL),
('storysec.v0310.chinese_pangu_yiwen_leiju.1','storyver.chinese.pangu_yiwen_leiju',1,'混沌如鸡蛋','Chaos like an egg','很久以前，天和地还没有分开，到处是一团混沌，样子像一个鸡蛋。盘古就生在这团混沌之中。','Long ago heaven and earth were not yet apart; everything was one chaos shaped like a hen''s egg, and Pangu was born inside it.','claim.v0310.china.pangu_egg','《艺文类聚》卷一引《三五历纪》；《太平御览》卷一引文字句略异。','原书已佚，只能依靠类书引文。'),
('storysec.v0310.chinese_pangu_yiwen_leiju.2','storyver.chinese.pangu_yiwen_leiju',2,'清者为天，浊者为地','Clear above, murky below','过了一万八千年，天地开辟：轻而清的阳气上升成为天，重而浊的阴气下沉成为地。盘古就在天地之间，一天之中变化九次，比天更神，比地更圣。','After 18,000 years heaven and earth opened: the light, clear yang rose to become heaven, the heavy, murky yin sank to become earth. Pangu stood between them, changing nine times a day, more divine than heaven and wiser than earth.','claim.v0310.china.pangu_separation','同一引文“阳清为天，阴浊为地”。',NULL),
('storysec.v0310.chinese_pangu_yiwen_leiju.3','storyver.chinese.pangu_yiwen_leiju',3,'一天长高一丈','A zhang a day','从此天每天升高一丈，地每天加厚一丈，盘古也每天长高一丈。这样又过了一万八千年，天高到了极点，地深到了极点，盘古也长到了极点。在这之后，才有了三皇。','From then on heaven rose a zhang each day, earth grew a zhang thicker, and Pangu grew a zhang taller. After another 18,000 years heaven was as high as it could be, earth as deep, and Pangu as tall. Only after that came the Three Sovereigns.','claim.v0310.china.pangu_growth','同一引文“天日高一丈……盘古日长一丈”。','“盘古垂死化身为日月山川”出自另一部书，本故事不合并。'),
('storysec.v0310.chinese_nezha_xiyouji_ch4.1','storyver.chinese.nezha_xiyouji_ch4',1,'天兵来讨','Heaven sends its army','孙悟空发现“弼马温”只是个看马的小官，一气之下回到花果山，自称“齐天大圣”。玉帝派托塔李天王和他的三太子哪吒，带领天兵前去捉拿。','Discovering that his title merely made him a keeper of horses, Sun Wukong storms back to his mountain and calls himself Great Sage Equal to Heaven. The Jade Emperor sends Heavenly King Li, bearer of the pagoda, and his third son Nezha with the heavenly troops to seize him.','claim.v0310.china.nezha_title','《西游记》第四回。',NULL),
('storysec.v0310.chinese_nezha_xiyouji_ch4.2','storyver.chinese.nezha_xiyouji_ch4',2,'三头六臂','Three heads, six arms','哪吒大喝一声，变成三头六臂，六只手各拿一件兵器打来。悟空见了，也变成三头六臂，把金箍棒一晃变成三条，六只手拿着架住。','Nezha gives a shout and becomes a figure with three heads and six arms, a weapon in every hand. Wukong does the same: he shakes his staff into three and parries with six hands.','claim.v0310.china.nezha_form','《西游记》第四回。',NULL),
('storysec.v0310.chinese_nezha_xiyouji_ch4.3','storyver.chinese.nezha_xiyouji_ch4',3,'毫毛分身','A hair becomes a double','两人斗得难分难解。悟空拔下一根毫毛，变成自己的模样继续迎敌，真身却绕到哪吒背后打了一棒。哪吒负痛败走，回去禀报父王：这猴子神通广大。','Neither can win. Wukong plucks a hair and turns it into a double of himself to keep fighting, while his true body circles behind Nezha and strikes. Nezha flees in pain and reports to his father that the monkey''s powers are great.','claim.v0310.china.wukong_defeats_nezha','《西游记》第四回。','这是小说情节，属于后世文学层。'),
('storysec.v0310.irish_mag_tuired_gray.1','storyver.irish.mag_tuired_gray',1,'达格达的大锅','The Dagda''s cauldron','达努神族带来了四件宝物，其中一件是从穆里亚斯城带来的达格达的大锅：凡是围着它吃饭的人，从没有一个是不饱足地离开的。','The Túatha Dé Danann brought four treasures. One was the Dagda''s cauldron from the city of Murias: no company that ate from it ever went away unsatisfied.','claim.v0310.irish.dagda_cauldron','Gray 本 §6。',NULL),
('storysec.v0310.irish_mag_tuired_gray.2','storyver.irish.mag_tuired_gray',2,'百艺之主来到塔拉','The master of all arts at Tara','鲁格来到塔拉的大门前，守门人问他会什么手艺。他报出一门又一门，而宫里每门手艺都已有人；最后他问：有没有一个人能同时精通所有这些？于是他以“百艺之主”的身份被请了进去。','Lug comes to the door of Tara, and the doorkeeper asks what art he brings. He names one after another, and each already has a master within — until he asks whether anyone there has all of them at once. So he is admitted as the Samildánach, master of all arts.','claim.v0310.irish.lugh_samildanach','Gray 本 §§53–72。',NULL),
('storysec.v0310.irish_mag_tuired_gray.3','storyver.irish.mag_tuired_gray',3,'萨温节的河边','By the river at Samain','萨温节前后，达格达在乌恩辛河边遇见一个女人正在洗东西，一只脚踩在南岸，一只脚踩在北岸。她就是莫莉甘。两人结合之后，她告诉达格达弗魔族将在哪里登陆，并许诺要取弗魔王因德赫的心血。','Around Samain the Dagda meets a woman washing at the river Unshin, one foot on the southern bank and one on the northern. She is the Morrígan. After they unite she tells him where the Fomoire will land and promises to take the heart''s blood of their king Indech.','claim.v0310.irish.dagda_morrigan','Gray 本 §84。',NULL),
('storysec.v0310.irish_mag_tuired_gray.4','storyver.irish.mag_tuired_gray',4,'第一次哀歌','The first keening','布里格是达格达的女儿，她和布雷斯的儿子鲁阿丹被派去刺杀铁匠戈伊布纽，却被戈伊布纽杀死。布里格赶来为儿子哀哭，先是尖声恸哭，最后低声啜泣——这是爱尔兰第一次听到哀歌与哭泣。','Rúadán, son of Bres and of Bríg the Dagda''s daughter, is sent to kill the smith Goibniu and is killed instead. Bríg comes and keens for her son, shrieking first and weeping at the end — the first time keening and weeping were heard in Ireland.','claim.v0310.irish.brig_keens','Gray 本 §§123–125。','文本写作 Bríg；与数据库中“布里吉德”实体的对应依学界通行用法。'),
('storysec.v0310.irish_mag_tuired_gray.5','storyver.irish.mag_tuired_gray',5,'巴洛尔的毒眼','Balor''s deadly eye','弗魔族勇士巴洛尔有一只毒眼，只在战场上睁开，要四个人用把手才能抬起眼皮。鲁格用投石一击，石头把那只眼睛从巴洛尔脑后打了出去，结果看见它的反而是他自己的军队。','The Fomorian champion Balor has a deadly eye, opened only on the battlefield, its lid lifted by four men with a handle. Lug casts a sling stone that drives the eye out through the back of Balor''s head, so that it is his own host that looks upon it.','claim.v0310.irish.lugh_kills_balor','Gray 本 §§133–135。',NULL),
('storysec.v0310.irish_mag_tuired_gray.6','storyver.irish.mag_tuired_gray',6,'莫莉甘宣告胜利','The Morrígan proclaims the victory','战斗结束后，恩玛斯的女儿莫莉甘把这场大胜宣告给爱尔兰的王者高地、神丘里的众灵、各条大河与河口，然后又说出关于未来的预言。','When the battle is won, the Morrígan, daughter of Ernmas, proclaims the great victory to the royal heights of Ireland, its síd-hosts, its chief waters and river-mouths — and then speaks prophecy.','claim.v0310.irish.morrigan_proclaims','Gray 本 §§166–167。','预言诗的内容未逐句建模。'),
('storysec.v0310.slavic_kyiv_idols_pvl.1','storyver.slavic.kyiv_idols_pvl',1,'山岗上的神像','Idols on the hill','《往年纪事》980 年条记载：弗拉基米尔开始在基辅独自为王，就在宫殿庭院外的山岗上立起一排神像。','The Primary Chronicle''s annal for 980 records that when Volodimer began to reign alone in Kyiv, he set up a row of idols on the hill outside the palace courtyard.','claim.v0310.slavic.pvl_980_witness','《往年纪事》980 年条。',NULL),
('storysec.v0310.slavic_kyiv_idols_pvl.2','storyver.slavic.kyiv_idols_pvl',2,'银头金须的佩伦','Perun with a silver head','最前面的是佩伦：木头雕成，头是银的，胡须是金的。','First stood Perun, carved of wood, with a silver head and a golden moustache.','claim.v060.slavic.perun_980_image','《往年纪事》980 年条。',NULL),
('storysec.v0310.slavic_kyiv_idols_pvl.3','storyver.slavic.kyiv_idols_pvl',3,'名单最后的莫科什','Mokosh at the end of the list','接下来是霍尔斯、达日博格、斯特里博格、西马尔格尔，名单的最后一位是莫科什。人们向这些神像献上祭品。编年史只记下了莫科什的名字，没有说她掌管什么。','Then came Khors, Dazhbog, Stribog and Simargl, and last on the list, Mokosh. People brought offerings to the idols. The chronicle records only Mokosh''s name, not what she governed.','claim.v0310.slavic.mokosh_980','《往年纪事》980 年条神名名单。','关于莫科什职能的说法来自其他材料与现代研究，本故事不补写。'),
('storysec.v0310.slavic_kyiv_idols_pvl.4','storyver.slavic.kyiv_idols_pvl',4,'988 年：神像倒下','988: the idols fall','八年后，弗拉基米尔受洗，下令推倒这些神像：有的砍碎，有的烧掉。佩伦被绑在马尾上拖下山，有人用棍子抽打，最后被扔进第聂伯河。','Eight years later Volodimer was baptized and ordered the idols overthrown — some cut to pieces, others burned. Perun was tied to a horse''s tail and dragged down the hill, beaten with sticks, and thrown into the Dnieper.','claim.v0310.slavic.perun_cast_down','《往年纪事》988 年条。','这是皈依一方的记载，不是对斯拉夫宗教的中立描述。'),
('storysec.v0310.zoroastrian_mihr_yasht_darmesteter.1','storyver.zoroastrian.mihr_yasht_darmesteter',1,'与造物主同样尊贵','As worthy as his maker','颂歌一开头，阿胡拉·马兹达对查拉图斯特拉说：我创造广阔牧场之主密特拉时，使他与我自己一样，值得献祭、值得祈祷。','The hymn opens with Ahura Mazda telling Zarathustra: when I created Mithra, lord of wide pastures, I made him as worthy of sacrifice and as worthy of prayer as myself.','claim.v0310.zoro.mithra_created','Yt 10.1。',NULL),
('storysec.v0310.zoroastrian_mihr_yasht_darmesteter.2','storyver.zoroastrian.mihr_yasht_darmesteter',2,'不可背弃契约','Never break the contract','对密特拉说谎、背弃契约的恶人，会给整个国家带来死亡。所以契约绝不可背弃——不论是与信徒订立的，还是与不信者订立的。','The wretch who lies to Mithra, breaking the contract, brings death upon the whole land. So the contract must never be broken, whether made with one of the faithful or with an unbeliever.','claim.v0310.zoro.mithra_contract','Yt 10.2。','“契约”是译者对 miθra 一词的理解，学界另有讨论。'),
('storysec.v0310.zoroastrian_mihr_yasht_darmesteter.3','storyver.zoroastrian.mihr_yasht_darmesteter',3,'千耳万眼','A thousand ears, ten thousand eyes','颂歌赞美密特拉说真话，是集会中的首领；他有一千只耳朵，一万只眼睛，什么都瞒不过他。','The hymn praises Mithra as truth-speaking, a chief in assemblies, with a thousand ears and ten thousand eyes — nothing escapes him.','claim.v0310.zoro.mithra_eyes','Yt 10.7。',NULL),
('storysec.v0310.zoroastrian_mihr_yasht_darmesteter.4','storyver.zoroastrian.mihr_yasht_darmesteter',4,'越过哈拉山','Over Mount Hara','每天清晨，他是天上诸神中第一个越过哈拉山的，比不朽的、驾着快马的太阳还要早。','Each morning he is the first of the heavenly gods to reach over Mount Hara, ahead of the undying, swift-horsed sun.','claim.v0310.zoro.mithra_hara','Yt 10.13。',NULL),
('storysec.v0310.zoroastrian_vd1_darmesteter.1','storyver.zoroastrian.vd1_darmesteter',1,'第一片良地','The first good land','阿胡拉·马兹达说：我所创造的良地中，第一片是雅利安瓦伊贾，在善河岱提亚旁边。','Ahura Mazda says: the first of the good lands I created was Airyana Vaejah, by the good river Daitya.','claim.v0310.zoro.airyana_vaejah','第一章第一片良地。','雅利安瓦伊贾不映射为现代坐标。'),
('storysec.v0310.zoroastrian_vd1_darmesteter.2','storyver.zoroastrian.vd1_darmesteter',2,'全然是死亡的对手','The one who is all death','随后，“全然是死亡”的安格拉·曼纽来了，他针对这片良地造出了河中之蛇和寒冬，那是恶魔们的作品。','Then came Angra Mainyu, who is all death, and against it he counter-created the serpent in the river and winter, a work of the daevas.','claim.v0310.zoro.angra_counter','第一章第一片良地。',NULL),
('storysec.v0310.zoroastrian_vd1_darmesteter.3','storyver.zoroastrian.vd1_darmesteter',3,'十六地，十六灾','Sixteen lands, sixteen plagues','名单一片接一片地继续：第二片是粟特人居住的平原，安格拉·曼纽就造出蝗虫。如此一共列出十六片良地，每一片都对应一种反创造的灾祸。','The list goes on land by land: the second is the plain where the Sughdhas dwell, and Angra Mainyu makes the locust. In all, sixteen good lands are named, each answered by a counter-created plague.','claim.v0310.zoro.locust','第一章第二片良地及以下。','译者认为这是宗教地理，混合了神话之地与真实国家；只有部分地名可以确认。'),
('storysec.v0310.hawaiian_pele_nps.1','storyver.hawaiian.pele_nps',1,'生在卡希基','Born in Kahiki','国家公园管理局介绍说，按照口述传统，佩蕾是夏威夷的火山之神，是一股自然之力，也是这些火山地貌的创造者。她出生在遥远的卡希基，为了给自己的火和家人寻找合适的家，乘船来到夏威夷群岛。','The National Park Service explains that, in oral history, Pele is the Hawaiian volcano deity, an elemental force and the creator of these volcanic landscapes. Born in the distant land of Kahiki, she voyaged to the Hawaiian Islands to find a suitable home for her fire and family.','claim.v0310.hawaii.pele_kahiki','NPS“Pele”与“Holo Mai Pele”页面。',NULL),
('storysec.v0310.hawaiian_pele_nps.2','storyver.hawaiian.pele_nps',2,'一路向东南','Island by island to the southeast','她一座岛一座岛地向东南迁移，寻找能安顿下来的地方。','She moved southeast through the islands, one after another, looking for a place to settle.','claim.v0310.hawaii.pele_southeast','NPS“Pele”页面。','各岛上的具体经历因版本而异，本站不补写。'),
('storysec.v0310.hawaiian_pele_nps.3','storyver.hawaiian.pele_nps',3,'哈雷茂茂的家','A home in Halemaʻumaʻu','最后她来到基拉韦厄山顶的哈雷茂茂火山口，把这里定为永久的家。据说她至今仍住在那里。','At last she came to Halemaʻumaʻu crater at the summit of Kīlauea and made it her permanent home. She is said to live there still.','claim.v0310.hawaii.pele_halemaumau','NPS 两页介绍。',NULL),
('storysec.v0310.hawaiian_pele_nps.4','storyver.hawaiian.pele_nps',4,'经过她的土地','Passing through her land','在夏威夷传统中，经过佩蕾的土地要先请求她的许可。国家公园管理局也请访客在这片神圣的地景中保持尊重。公园还提醒：不同的 moʻolelo 版本可能差别很大。','In Hawaiian tradition it is customary to ask Pele''s permission to travel through her land, and the park asks visitors to behave respectfully in this sacred landscape. It also notes that versions of the moʻolelo may differ, sometimes greatly.','claim.v0310.hawaii.pele_permission','NPS“Pele”页面。','这里只讲公开概述；家族与地方传统不在收集范围。'),
('storysec.v0310.maori_creation_common_threads.1','storyver.maori.creation_common_threads',1,'从黑暗中出现','Out of darkness','Te Ara 写道：在毛利传统中，创世的核心行动是天与地的分离。故事从黑暗与虚无开始，天父兰吉努伊与地母帕帕图阿努库从中出现。起初天地紧紧相连，他们的孩子就出生在两者之间。','Te Ara writes that in Māori tradition the central act of creation is the separation of earth and sky. The story begins in darkness and nothingness, from which Ranginui the sky father and Papatūānuku the earth mother emerge. At first earth and sky are joined, and their children are born between them.','claim.v0310.maori.rangi_papa_joined','Te Ara“毛利创世传统”第1页。',NULL),
('storysec.v0310.maori_creation_common_threads.2','storyver.maori.creation_common_threads',2,'孩子们分开父母','The children part their parents','孩子们决定把父母分开。天与地一旦分离，光就照进了世界——从黑暗走向光明，正是由孩子们的这一行动完成的。','The children decide to separate their parents. Once earth and sky are apart, light enters the world: the move from darkness to light is achieved by the children''s act.','claim.v0310.maori.ranginui_separated','同一页面。','Te Ara 说明：在部分部族版本中，塔内在分开天地时起重要作用；本站不选定某一部族的说法。'),
('storysec.v0310.maori_creation_common_threads.3','storyver.maori.creation_common_threads',3,'自然的众神','Atua of the natural world','分离之后，孩子们成为自然各部分的神（atua）：塔内是森林之神，塔加罗阿是海洋之神，还有地震之神鲁奥莫科、风与天气之神塔维里马特阿。把这些神编进同一个谱系，是毛利人解释自然世界的传统方式。','After the separation the children become atua of different parts of nature: Tāne of the forests, Tangaroa of the sea, Rūaumoko of earthquakes, Tāwhirimātea of winds and weather. Weaving these atua into one genealogy is the traditional Māori way of explaining the natural world.','claim.v0310.maori.tane_forests','同一页面。','鲁奥莫科与塔维里马特阿尚未建立独立实体。'),
('storysec.v0310.maori_creation_common_threads.4','storyver.maori.creation_common_threads',4,'不是只有一个版本','Not a single version','Te Ara 也提醒，各部族的创世故事差异很大，特别是关于至高存在的角色。这里只讲公开页面所总结的共同线索，具名部族的版本须经相应权威授权。','Te Ara also cautions that tribal versions vary considerably, especially on the role of a supreme being. This retelling covers only the common threads the public page summarizes; named iwi versions require permission from the appropriate authority.','claim.v0310.maori.diversity','Te Ara 故事摘要。','具名 iwi／hapū 版本仍为权限阻塞。');

