INSERT OR IGNORE INTO story_event_nodes(
    id,story_version_id,event_order,title_zh,title_en,summary_zh,summary_en,anchor_claim_id,event_entity_id,place_entity_id,location_kind,coordinate_policy,evidence_status,uncertainty_note,created_at
) VALUES
('storyevent.v0310.egyptian_heliopolis_ucl.1','storyver.egyptian.heliopolis_ucl',1,'太阳神的第一对子女','The creator''s first pair','在埃及的创世观念里，主要的创造者是太阳神，他也被称为阿图姆。','In Egyptian creation thought the principal creator is the sun-god, also called Atum.','claim.v0310.egypt.shu_child_atum','event.egyptian.separation_geb_nut',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','“干燥／湿润”是现代学者的词源解释。','2026-10-09T00:30:00Z'),
('storyevent.v0310.egyptian_heliopolis_ucl.2','storyver.egyptian.heliopolis_ucl',2,'大地与天空出生','Earth and sky are born','舒和泰芙努特又生下两个孩子：大地之神盖布和天空女神努特。','Shu and Tefnet in turn produce two children: Geb, god of the earth, and Nut, goddess of the sky — dryness and moisture crystallised into solid earth and a sky the Egyptians thought of as watery.','claim.v0310.egypt.geb_child_shu','event.egyptian.separation_geb_nut',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.egyptian_heliopolis_ucl.3','storyver.egyptian.heliopolis_ucl',3,'舒把天地分开','Shu holds earth and sky apart','盖布和努特被舒分开，天在上、地在下。','Shu separates Geb and Nut, sky above and earth below.','claim.v0310.egypt.shu_separation','event.egyptian.separation_geb_nut',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','这是学者对零散材料的归纳，不是单一文本的原话。','2026-10-09T00:30:00Z'),
('storyevent.v0310.egyptian_heliopolis_ucl.4','storyver.egyptian.heliopolis_ucl',4,'塞特、奥西里斯与伊西斯','Seth, Osiris and Isis','后来，奥西里斯“无序的兄弟”塞特出于嫉妒杀害了他，把遗体分开，并取代他成为世界之王。','Later Osiris''s anarchic brother Seth, out of jealousy, murders him, dismembers him and takes his place as king of the world.','claim.v0310.egypt.seth_kills_osiris','event.egyptian.separation_geb_nut',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','古代文献中这个故事有许多版本；本站不合成“标准版”。','2026-10-09T00:30:00Z'),
('storyevent.v0310.egyptian_heavenly_cow_ucl.1','storyver.egyptian.heavenly_cow_ucl',1,'人类反叛拉','Humankind rebels against Ra','一部新王国时期的宗教文献记载：人们起来反叛太阳神拉。','A New Kingdom religious composition records that people rebel against the sun-god Ra.','claim.v0310.egypt.ra_rebellion','event.egyptian.heavenly_cow_punishment',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.egyptian_heavenly_cow_ucl.2','storyver.egyptian.heavenly_cow_ucl',2,'眼睛化作塞赫麦特','The Eye becomes Sekhmet','拉把自己的眼睛从身体里派出去，成为一个独立的“女儿”。','Ra sends his Eye out from his body as a separate offshoot, a ''daughter''.','claim.v0310.egypt.sekhmet_eye_of_ra','event.egyptian.heavenly_cow_punishment',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','“强大的女神”是 UCL 给出的释义。','2026-10-09T00:30:00Z'),
('storyevent.v0310.egyptian_heavenly_cow_ucl.3','storyver.egyptian.heavenly_cow_ucl',3,'一湖红色的啤酒','A lake of red beer','众神用计：他们把一湖啤酒染成红色，看起来像人血。','The gods play a trick: they colour a lake of beer red to look like human blood.','claim.v0310.egypt.sekhmet_to_hathor','event.egyptian.heavenly_cow_punishment',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','这是故事中的性格转变；数据库不把两位女神合并为同一实体。','2026-10-09T00:30:00Z'),
('storyevent.v0310.egyptian_weighing_ani_bm.1','storyver.egyptian.weighing_ani_bm',1,'心脏与羽毛','A heart and a feather','画面中央是一座天平。','At the centre stands a balance.','claim.v0310.egypt.ani_depicts_weighing','event.egyptian.weighing_heart_ani',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.egyptian_weighing_ani_bm.2','storyver.egyptian.weighing_ani_bm',2,'阿努比斯扶稳天平','Anubis steadies the balance','胡狼头的阿努比斯跪在天平旁，拉着右边秤盘的绳子，扶稳天平的铅锤。','Jackal-headed Anubis kneels by the balance, holding the cord of the right-hand pan and steadying its plumb bob.','claim.v0310.egypt.anubis_weighing','event.egyptian.weighing_heart_ani',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.egyptian_weighing_ani_bm.3','storyver.egyptian.weighing_ani_bm',3,'托特准备记录','Thoth stands ready to record','托特在画中出现两次：一只小狒狒坐在天平顶端；右边站着朱鹭头的“众神书吏”，手持调色板和芦苇笔，准备记下审问的结果。','Thoth appears twice: as a small baboon sitting on top of the balance, and as the ibis-headed scribe of the gods standing to the right with palette and reed, ready to write down the result.','claim.v0310.egypt.thoth_weighing','event.egyptian.weighing_heart_ani',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','称量的最终结果和吞噬心脏的怪兽不在这条博物馆描述里，本站不补写。','2026-10-09T00:30:00Z'),
('storyevent.v0310.egyptian_mourning_sisters_met.1','storyver.egyptian.mourning_sisters_met',1,'举手掩面的奈芙蒂斯','Nephthys raises her hand','这尊小木像跪在地上，一只手举到脸前，是古埃及的哀悼姿势。','The small wooden figure kneels and raises one hand before her face, an Egyptian gesture of mourning.','claim.v0310.egypt.nephthys_figure',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.egyptian_mourning_sisters_met.2','storyver.egyptian.mourning_sisters_met',2,'和伊西斯成对','A pair with Isis','博物馆说明，这尊像和另一尊伊西斯像（12.182.23b）是一对，两位女神以同样的姿势哀悼。','The museum states that the figure forms a pair with a figure of Isis (12.182.23b), the two goddesses mourning in the same posture.','claim.v0310.egypt.mourners_pair',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.egyptian_mourning_sisters_met.3','storyver.egyptian.mourning_sisters_met',3,'守在奥西里斯身旁','Beside the body of Osiris','在古埃及图像中，这两位哀悼女神陪伴在奥西里斯的遗体旁，一左一右。','In Egyptian representations the two mourning goddesses accompany the body of Osiris, one at each end.','claim.v0310.egypt.nephthys_mourns_osiris',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','“放在棺椁两端”是博物馆的推测，不是出土记录。','2026-10-09T00:30:00Z'),
('storyevent.v0310.japanese_izanagi_izanami_kojiki.1','storyver.japanese.izanagi_izanami_kojiki',1,'天浮桥上的长矛','A spear from the Floating Bridge','天上的众神命令伊邪那岐和伊邪那美去巩固还在漂浮的大地，并交给他们一支镶玉的天沼矛。','The heavenly deities command Izanagi and Izanami to make firm the drifting land and give them a jewelled spear.','claim.v0310.japan.onogoro_result','event.japanese.onogoro_creation',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','《日本书纪》说两神是自己决定动手，本版不合并。','2026-10-09T00:30:00Z'),
('storyevent.v0310.japanese_izanagi_izanami_kojiki.2','storyver.japanese.izanagi_izanami_kojiki',2,'火神出生','The birth of the fire deity','两神结合，生出许多岛屿和神灵。','Joined together, the pair bring forth islands and deities.','claim.v0310.japan.izanami_death','event.japanese.onogoro_creation',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.japanese_izanagi_izanami_kojiki.3','storyver.japanese.izanagi_izanami_kojiki',3,'追到黄泉','Following her to Yomi','伊邪那岐想再见到妻子，便追到黄泉，请她回去：“我们造的国土还没有完成。','Longing to see her, Izanagi follows Izanami to Yomi and asks her to come back, for the lands they made are not yet finished.','claim.v0310.japan.izanagi_yomi','event.japanese.onogoro_creation',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','之后的逃离情节可参看本库“黄泉中的八雷神”故事。','2026-10-09T00:30:00Z'),
('storyevent.v0310.japanese_izanagi_izanami_kojiki.4','storyver.japanese.izanagi_izanami_kojiki',4,'洗出三位贵神','Three deities born of washing','伊邪那岐回来后在水中洗净自己，身上不断化生出神。','Back from Yomi, Izanagi bathes to purify himself, and deities are born as he washes.','claim.v0310.japan.tsukuyomi_born','event.japanese.onogoro_creation',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','三神的通行名称来自译者注释。','2026-10-09T00:30:00Z'),
('storyevent.v0310.norse_vanir_gylf.1','storyver.norse.vanir_gylf',1,'海风之神尼奥尔德','Njörðr of wind and sea','尼奥尔德住在天上一个叫诺欧通的地方。','Njörðr lives in heaven at a place called Nóatún.','claim.v0310.norse.njord_wind_sea',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.norse_vanir_gylf.2','storyver.norse.vanir_gylf',2,'弗雷与芙蕾雅','Freyr and Freyja','尼奥尔德有一儿一女。','Njörðr has a son and a daughter.','claim.v0310.norse.freyja_slain',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.norse_vanir_gylf.3','storyver.norse.vanir_gylf',3,'弗雷交出宝剑','Freyr gives away his sword','后来，弗雷爱上了巨人之女葛德。','Later Freyr falls in love with Gerðr, a giant''s daughter.','claim.v0310.norse.freyr_sword',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','葛德尚未单独建立实体；诸神黄昏中的后果另行登记。','2026-10-09T00:30:00Z'),
('storyevent.v0310.norse_tyr_gylf.1','storyver.norse.tyr_gylf',1,'最勇敢的神','The boldest god','斯诺里说，提尔是众神中最勇敢、最无畏的一位，打仗时人们向他祈求胜利。','Snorri says Týr is the boldest and most valiant of the gods, invoked for victory in battle — and he has only one hand.','claim.v0310.norse.tyr_brave','event.norse.binding_of_fenrir',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.norse_tyr_gylf.2','storyver.norse.tyr_gylf',2,'一只手作担保','A hand as a pledge','众神想用一条魔法绳索捆住狼芬里尔。','The gods mean to bind the wolf Fenrir with a magic fetter.','claim.v0310.norse.tyr_fenrir','event.norse.binding_of_fenrir',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.norse_tyr_gylf.3','storyver.norse.tyr_gylf',3,'狼咬断了手','The wolf bites','绳索越挣越紧，狼发现自己被骗了，便咬断了提尔的手。','The more the wolf struggles, the tighter the fetter grows.','claim.v0310.norse.fenrir_bound','event.norse.binding_of_fenrir',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.norse_heimdall_gylf.1','storyver.norse.heimdall_gylf',1,'桥头的守望者','Watchman at the bridge','海姆达尔是众神的守望者。','Heimdallr is the watchman of the gods.','claim.v0310.norse.heimdall_watchman',NULL,'place.norse.himinbjorg','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-09T00:30:00Z'),
('storyevent.v0310.norse_heimdall_gylf.2','storyver.norse.heimdall_gylf',2,'看得远，听得清','Keen eyes and ears','他需要的睡眠比鸟还少，无论白天黑夜都能看见一百里远；他还能听见草在地上生长、羊毛在羊身上生长的声音。','He needs less sleep than a bird and sees a hundred leagues by day or night; he can hear grass growing in the ground and wool growing on sheep.','claim.v0310.norse.heimdall_senses',NULL,'place.norse.himinbjorg','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-09T00:30:00Z'),
('storyevent.v0310.norse_heimdall_gylf.3','storyver.norse.heimdall_gylf',3,'加拉尔号角与九位母亲','Gjallarhorn and nine mothers','海姆达尔有一支号角，叫加拉尔号角，吹响时所有世界都能听见。','Heimdallr has a horn called Gjallarhorn, whose blast is heard in all worlds.','claim.v0310.norse.heimdall_horn',NULL,'place.norse.himinbjorg','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','九位母亲的名字见其他诗篇，本版不列出。','2026-10-09T00:30:00Z'),
('storyevent.v0310.norse_ymir_gylf.1','storyver.norse.ymir_gylf',1,'冰与火之间','Between ice and fire','世界还不存在时，只有一道叫金伦加的深渊。','Before the world exists there is only the void of Ginnungagap.','claim.v0310.norse.ymir_origin','event.norse.slaying_of_ymir',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.norse_ymir_gylf.2','storyver.norse.ymir_gylf',2,'奥丁兄弟杀死尤弥尔','Odin and his brothers kill Ymir','布尔的儿子们——奥丁、维利和维——杀死了巨人尤弥尔。','The sons of Borr — Odin, Vili and Vé — kill the giant Ymir.','claim.v0310.norse.odin_kills_ymir','event.norse.slaying_of_ymir',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.norse_ymir_gylf.3','storyver.norse.ymir_gylf',3,'用身体造世界','A world made from a body','他们用尤弥尔的身体造出世界：肉变成大地，血变成海洋和湖泊，骨头变成山岩，头骨被举起来成为天空。','From Ymir''s body they make the world: his flesh becomes the earth, his blood the sea and lakes, his bones the rocks, and his skull is raised up as the sky.','claim.v0310.norse.ymir_world','event.norse.slaying_of_ymir',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','斯诺里的散文综述与诗歌见证可能有细节差异。','2026-10-09T00:30:00Z'),
('storyevent.v0310.norse_frigg_gylf.1','storyver.norse.frigg_gylf',1,'知晓命运的女神','The goddess who knows all fates','弗丽嘉是奥丁的妻子。','Frigg is Odin''s wife.','claim.v0310.norse.frigg_wife','event.norse.death_of_baldr',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.norse_frigg_gylf.2','storyver.norse.frigg_gylf',2,'万物发誓','Everything swears','巴德尔做了不祥的梦。','Baldr has ominous dreams, so Frigg makes fire, water, iron and all metals, stones, earth, trees, sicknesses, beasts, birds and serpents swear not to harm him.','claim.v0310.norse.frigg_oaths','event.norse.death_of_baldr',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.norse_frigg_gylf.3','storyver.norse.frigg_gylf',3,'槲寄生','The mistletoe','众神以为巴德尔刀枪不入，便拿东西扔他取乐。','Believing Baldr unharmable, the gods amuse themselves by throwing things at him.','claim.v0310.norse.baldr_death','event.norse.death_of_baldr',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','投掷者与幕后之人的情节将在后续批次逐段登记。','2026-10-09T00:30:00Z'),
('storyevent.v0310.mexica_coatepec_fc.1','storyver.mexica.coatepec_fc',1,'一团羽毛','A ball of feathers','科阿特利库埃住在蛇山上。','Coatlicue lives on Coatepec.','claim.v0310.mexica.coatlicue_feathers','event.mexica.birth_of_huitzilopochtli','place.mexica.coatepec','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-09T00:30:00Z'),
('storyevent.v0310.mexica_coatepec_fc.2','storyver.mexica.coatepec_fc',2,'兄妹要杀母亲','Her children turn against her','她的女儿科约尔沙乌基对兄弟们——四百个南方人——说：母亲让我们蒙羞，我们必须杀了她。','Her daughter Coyolxauhqui tells her brothers, the four hundred Centzon Huitznahua, that their mother has shamed them and must be killed.','claim.v0310.mexica.coyol_event','event.mexica.birth_of_huitzilopochtli','place.mexica.coatepec','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-09T00:30:00Z'),
('storyevent.v0310.mexica_coatepec_fc.3','storyver.mexica.coatepec_fc',3,'全副武装地出生','Born fully armed','腹中的维齐洛波奇特利安慰母亲：不要怕，我知道该怎么做。','From the womb Huitzilopochtli comforts his mother: do not be afraid, I know what to do.','claim.v0310.mexica.huitz_armed','event.mexica.birth_of_huitzilopochtli','place.mexica.coatepec','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-09T00:30:00Z'),
('storyevent.v0310.mexica_coatepec_fc.4','storyver.mexica.coatepec_fc',4,'山顶的胜利','Victory on the summit','维齐洛波奇特利砍下科约尔沙乌基的头，她的身体沿着蛇山滚落下去。','Huitzilopochtli cuts off Coyolxauhqui''s head, and her body tumbles down the side of Coatepec.','claim.v0310.mexica.huitz_kills_coyol','event.mexica.birth_of_huitzilopochtli','place.mexica.coatepec','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','学者认为这段叙事与大神庙的布局相呼应，属于解释，不写成事实。','2026-10-09T00:30:00Z'),
('storyevent.v0310.mexica_tollan_fc.1','storyver.mexica.tollan_fc',1,'被当作神的蒂特拉卡瓦','Titlacauan, held to be a god','第三卷第2章讲人们怎样把一位叫蒂特拉卡瓦、也叫特斯卡特利波卡的人物当作神来敬奉。','Chapter 2 of Book 3 tells how one called Titlacauan, or Tezcatlipoca, came to be regarded as a god.','claim.v0310.mexica.tezca_titlacauan','event.mexica.quetzalcoatl_tollan_end',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.mexica_tollan_fc.2','storyver.mexica.tollan_fc',2,'图拉的大法师','The great wizard of Tollan','第3章讲羽蛇神——图拉的一位大法师。','Chapter 3 tells of Quetzalcoatl, a great wizard at Tollan.','claim.v0310.mexica.quetzal_event','event.mexica.quetzalcoatl_tollan_end',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','本段依据章节标题与概要，具体情节尚未逐句核对。','2026-10-09T00:30:00Z'),
('storyevent.v0310.mexica_tollan_fc.3','storyver.mexica.tollan_fc',3,'雪山之间','Between the snow mountains','第14章记载，羽蛇神离去时，追随他的人经过伊斯塔克特佩特尔与波波卡特佩特尔两座雪山之间，被冻死在冰雪里。','Chapter 14 records that as Quetzalcoatl departs, his vassals freeze to death in the ice as they pass between Iztactepetl and Popocatepetl.','claim.v0310.mexica.vassals_froze','event.mexica.quetzalcoatl_tollan_end',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.mexica_templo_mayor_inah.1','storyver.mexica.templo_mayor_inah',1,'南边的战神','The war god on the south','大神庙南侧的神殿属于维齐洛波奇特利——墨西加人的太阳战神，也是他们的守护神。','The southern chapel of the Templo Mayor belongs to Huitzilopochtli, the Mexica''s solar god of war and their patron.','claim.v0310.mexica.huitz_templo',NULL,'site.mexico.templo_mayor','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-09T00:30:00Z'),
('storyevent.v0310.mexica_templo_mayor_inah.2','storyver.mexica.templo_mayor_inah',2,'北边的雨神','The rain god on the north','北侧的神殿属于特拉洛克——掌管雨水、与农业紧密相连的神。','The northern temple belongs to Tlaloc, god of rain and closely tied to agriculture.','claim.v0310.mexica.tlaloc_templo',NULL,'site.mexico.templo_mayor','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-09T00:30:00Z'),
('storyevent.v0310.mexica_templo_mayor_inah.3','storyver.mexica.templo_mayor_inah',3,'一层层长高的神庙','A temple that grew in layers','据 INAH 介绍，墨西加人在1325年建立特诺奇蒂特兰时修了一座小神庙，此后经过多次重建和扩建，越修越高。','According to INAH, the Mexica built a small temple when they founded Tenochtitlan in 1325, and it was rebuilt and enlarged many times over.','claim.v0310.mexica.templo_layers',NULL,'site.mexico.templo_mayor','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','各建造阶段的具体年代仍有不确定之处。','2026-10-09T00:30:00Z'),
('storyevent.v0310.maya_kukulkan_unesco.1','storyver.maya.kukulkan_unesco',1,'奇琴伊察的金字塔','A pyramid at Chichen-Itza','奇琴伊察是尤卡坦半岛上的前西班牙时期古城，已列入世界遗产名录。','Chichen-Itza is a pre-Hispanic city on the Yucatán peninsula, inscribed on the World Heritage List.','claim.v0310.maya.castillo_part',NULL,'monument.maya.el_castillo_chichen','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-09T00:30:00Z'),
('storyevent.v0310.maya_kukulkan_unesco.2','storyver.maya.kukulkan_unesco',2,'库库尔坎神庙','The Temple of Kukulkan','奇琴伊察北区最重要的建筑是卡斯蒂略金字塔，联合国教科文组织的记录说，它又被称为“库库尔坎神庙”。','The chief monument of Chichen-Itza''s northern group is El Castillo, which UNESCO''s record says is also known as the Temple of Kukulkan.','claim.v0310.maya.castillo_kukulkan',NULL,'monument.maya.el_castillo_chichen','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-09T00:30:00Z'),
('storyevent.v0310.maya_kukulkan_unesco.3','storyver.maya.kukulkan_unesco',3,'一个名字的翻译','A name in translation','同一记录提到一种最常见的说法：图拉之王“一芦苇·托皮尔钦·羽蛇”占领了这座城市，而“库库尔坎”正是玛雅人对“羽蛇”这个名字的翻译。','The same record cites the most common version: the King of Tula, Ce Acatl Topiltzin Quetzalcoatl, took the city — and ''Kukulkan'' is how the Maya translated his name.','claim.v0310.maya.kukulkan_name',NULL,'monument.maya.el_castillo_chichen','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','这是关于统治者名号的传统说法，不把玛雅与墨西加的神合并为同一实体。','2026-10-09T00:30:00Z'),
('storyevent.v0310.maya_chahk_met.1','storyver.maya.chahk_met',1,'水中的雨神','The rain god in the water','这只古典期的玛雅陶盘上，雨神恰克半身浸在水波纹里，四周写着表示“海”的象形文字。','On this Classic Maya plate the rain god Chahk stands waist-deep in watery motifs, surrounded by hieroglyphs for ''sea''.','claim.v0310.maya.chahk_plate',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.maya_chahk_met.2','storyver.maya.chahk_met',2,'Chahk 这个名字','The name Chahk','在古典期的玛雅象形文字里，这位雨神的名字写作 Chahk；人们常写的“恰克”就是这个名字。','In Classic-period Maya hieroglyphs the rain god''s name is written Chahk — the familiar ''Chaac''.','claim.v0310.maya.chahk_name',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.maya_chahk_met.3','storyver.maya.chahk_met',3,'进入博物馆','Into the museum','这只陶盘在 2021 年由 Mol 收藏捐赠给大都会艺术博物馆。','The plate entered The Metropolitan Museum of Art in 2021 as a gift of the Mol Collection.','claim.v0310.maya.chahk_held_met',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','这是物质见证，本站不补写神话情节。','2026-10-09T00:30:00Z'),
('storyevent.v0310.maya_itzamnaaj_met.1','storyver.maya.itzamnaaj_met',1,'年老的天神','The aged god','2022 年的展览按“众神的一生”展开：从婴儿、壮年到老年。','The 2022 exhibition followed the gods through life — infancy, prime and old age.','claim.v0310.maya.itzamnaaj_aged',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.maya_itzamnaaj_met.2','storyver.maya.itzamnaaj_met',2,'名字仍有疑问','A name still in question','“Itzamnaaj”是殖民时期尤卡坦一位重要神祇的名字。','''Itzamnaaj'' is the name of a major deity in colonial Yucatán.','claim.v0310.maya.itzamnaaj_name',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','名字读法未定，本站同时保留“伊察姆纳”与“Itzamnaaj”。','2026-10-09T00:30:00Z'),
('storyevent.v0310.maya_itzamnaaj_met.3','storyver.maya.itzamnaaj_met',3,'故事还要等更多见证','The story awaits more witnesses','这里依据的是一份现代展览介绍，而不是古代文本。','This version rests on a modern exhibition text, not an ancient one.','claim.v0310.maya.itzamnaaj_scope',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','待找到可定位的古代或殖民时期文本见证后再扩充。','2026-10-09T00:30:00Z'),
('storyevent.v0310.sumerian_enki_ninhursag_etcsl.1','storyver.sumerian.enki_ninhursag_etcsl',1,'纯净的迪尔蒙','Pure Dilmun','故事开头描写迪尔蒙：一片纯净、安宁的土地，一切都还处在最初的状态。','The composition opens with Dilmun, a pure and peaceful land where everything is still in its first state.','claim.v0310.sumer.dilmun_setting','event.sumerian.enki_ninhursag','place.sumerian.dilmun','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话中的迪尔蒙不等同于历史上的同名地区。','2026-10-09T00:30:00Z'),
('storyevent.v0310.sumerian_enki_ninhursag_etcsl.2','storyver.sumerian.enki_ninhursag_etcsl',2,'吃下植物，招来诅咒','Eating the plants brings a curse','恩基把那里长出的植物一一吃掉。','Enki eats the plants that have grown there, one after another.','claim.v0310.sumer.ninhursag_curse','event.sumerian.enki_ninhursag','place.sumerian.dilmun','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','具体植物名单尚未逐项建模。','2026-10-09T00:30:00Z'),
('storyevent.v0310.sumerian_enki_ninhursag_etcsl.3','storyver.sumerian.enki_ninhursag_etcsl',3,'为每一处病痛生出神','A deity for every ailment','后来宁胡尔萨格回到恩基身边。','Later Ninhursaĝa returns to Enki.','claim.v0310.sumer.ninhursag_heals','event.sumerian.enki_ninhursag','place.sumerian.dilmun','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-09T00:30:00Z'),
('storyevent.v0310.sumerian_nanna_journey_etcsl.1','storyver.sumerian.nanna_journey_etcsl',1,'想念父亲的城市','Longing for his father''s city','英勇的南纳一心想着父亲的城市——尼普尔。','Heroic Nanna-Suen sets his mind on his father''s city, Nibru.','claim.v0310.sumer.nanna_child_enlil','event.sumerian.nanna_journey','site.iraq.nippur','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-09T00:30:00Z'),
('storyevent.v0310.sumerian_nanna_journey_etcsl.2','storyver.sumerian.nanna_journey_etcsl',2,'满船的礼物','A boat full of gifts','他准备了一条船，装满各种礼物，顺着河道一路航行，前往尼普尔。','He prepares a boat, loads it with gifts and sails along the waterways toward Nibru.','claim.v0310.sumer.nanna_journey','event.sumerian.nanna_journey','site.iraq.nippur','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','沿途停靠的城市尚未逐项登记。','2026-10-09T00:30:00Z'),
('storyevent.v0310.sumerian_nanna_journey_etcsl.3','storyver.sumerian.nanna_journey_etcsl',3,'带回乌尔的祝福','Blessings for Urim','恩利尔欢迎儿子的到来，赐给他丰饶的物产，让他带回自己的城市乌尔。','Enlil welcomes his son and grants him abundance to take back to his own city, Urim.','claim.v0310.sumer.enlil_blesses','event.sumerian.nanna_journey','site.iraq.nippur','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','学者把这首诗与城市间运送供品的仪式相联系，属于解释层。','2026-10-09T00:30:00Z'),
('storyevent.v0310.sumerian_gilgamesh_huwawa_etcsl.1','storyver.sumerian.gilgamesh_huwawa_etcsl',1,'要进山去','To the mountains','吉尔伽美什决定动身进山。','Gilgameš resolves to set off for the mountains.','claim.v0310.sumer.gilgamesh_event','event.sumerian.gilgamesh_huwawa',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.sumerian_gilgamesh_huwawa_etcsl.2','storyver.sumerian.gilgamesh_huwawa_etcsl',2,'先告诉乌图','First tell Utu','恩奇都说：山是乌图管的，这件事应该先让乌图知道。','Enkidu says the mountains are Utu''s concern, so Utu should be told of the plan.','claim.v0310.sumer.utu_told','event.sumerian.gilgamesh_huwawa',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.sumerian_gilgamesh_huwawa_etcsl.3','storyver.sumerian.gilgamesh_huwawa_etcsl',3,'眼泪换来的向导','Guides granted for tears','吉尔伽美什向乌图祈求。','Gilgameš prays to Utu, who accepts his tears as a gift and grants him seven warriors to guide him toward Ḫuwawa.','claim.v0310.sumer.utu_helps','event.sumerian.gilgamesh_huwawa',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','七位勇士的具体身份描述尚未逐句建模。','2026-10-09T00:30:00Z'),
('storyevent.v0310.chinese_fuxi_xici.1','storyver.chinese.fuxi_xici',1,'包牺氏治理天下','When Baoxi ruled the world','《系辞下》讲古代圣人的发明，第一位就是包牺氏——后世通常写作伏羲。','Xi Ci II lists the inventions of the ancient sages, and the first is Baoxi — usually written Fuxi in later texts.','claim.v0310.china.fuxi_baoxi','event.chinese.fuxi_makes_trigrams',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','“包牺”即“伏羲”是传统注疏的读法。','2026-10-09T00:30:00Z'),
('storyevent.v0310.chinese_fuxi_xici.2','storyver.chinese.fuxi_xici',2,'仰观天，俯察地','Looking up, looking down','他抬头观察天上的日月星辰，低头观察大地的形势；又细看鸟兽身上的花纹，看各地适合生长什么。','He looked up at the images in the sky and down at the patterns of the earth; he studied the markings of birds and beasts and what each land was suited for.','claim.v0310.china.fuxi_observes','event.chinese.fuxi_makes_trigrams',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.chinese_fuxi_xici.3','storyver.chinese.fuxi_xici',3,'画出八卦','The first eight trigrams','于是他开始画出八卦——八个由三条线组成的符号，用来通达神明的德性，把万物的情状分门别类。','Thereupon he first made the eight trigrams — eight figures of three lines each — to communicate with spirit-like virtue and to sort the dispositions of the myriad things.','claim.v0310.china.fuxi_bagua','event.chinese.fuxi_makes_trigrams',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.chinese_fuxi_xici.4','storyver.chinese.fuxi_xici',4,'结绳为网','Cords become nets','他还把绳子打结，做成罗网，人们用它打猎、捕鱼。','He also knotted cords into nets, which people used to hunt and fish.','claim.v0310.china.fuxi_nets','event.chinese.fuxi_makes_trigrams',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','后续圣人的发明不在本故事范围内。','2026-10-09T00:30:00Z'),
('storyevent.v0310.chinese_zhuolu_shiji.1','storyver.chinese.zhuolu_shiji',1,'神农氏衰落','Shennong''s line declines','黄帝是少典的儿子，姓公孙，名轩辕。','The Yellow Emperor was the son of Shaodian, surnamed Gongsun and named Xuanyuan.','claim.v0310.china.huangdi_identity','event.chinese.battle_of_zhuolu',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','此前轩辕与炎帝在阪泉的三次交战本故事未展开。','2026-10-09T00:30:00Z'),
('storyevent.v0310.chinese_zhuolu_shiji.2','storyver.chinese.zhuolu_shiji',2,'蚩尤作乱','Chiyou rebels','诸侯之中，蚩尤最为凶暴，没有人能制服他。','Among the lords Chiyou was the most violent, and no one could subdue him.','claim.v0310.china.chiyou_rebels','event.chinese.battle_of_zhuolu',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.chinese_zhuolu_shiji.3','storyver.chinese.zhuolu_shiji',3,'涿鹿之野','In the wilds of Zhuolu','轩辕征召各路诸侯的军队，在涿鹿的原野上与蚩尤交战，终于把蚩尤擒住并杀死。','Xuanyuan called up the armies of the lords and fought Chiyou in the wilds of Zhuolu, and at last captured and killed him.','claim.v0310.china.huangdi_kills_chiyou','event.chinese.battle_of_zhuolu',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','涿鹿不在本站映射为现代坐标。','2026-10-09T00:30:00Z'),
('storyevent.v0310.chinese_zhuolu_shiji.4','storyver.chinese.zhuolu_shiji',4,'尊为天子','Honoured as Son of Heaven','诸侯们都尊奉轩辕为天子，取代了神农氏，这就是黄帝。','The lords all honoured Xuanyuan as Son of Heaven in place of Shennong: this was the Yellow Emperor.','claim.v0310.china.huangdi_son_of_heaven','event.chinese.battle_of_zhuolu',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.chinese_pangu_yiwen_leiju.1','storyver.chinese.pangu_yiwen_leiju',1,'混沌如鸡蛋','Chaos like an egg','很久以前，天和地还没有分开，到处是一团混沌，样子像一个鸡蛋。','Long ago heaven and earth were not yet apart; everything was one chaos shaped like a hen''s egg, and Pangu was born inside it.','claim.v0310.china.pangu_egg','event.chinese.pangu_heaven_earth',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','原书已佚，只能依靠类书引文。','2026-10-09T00:30:00Z'),
('storyevent.v0310.chinese_pangu_yiwen_leiju.2','storyver.chinese.pangu_yiwen_leiju',2,'清者为天，浊者为地','Clear above, murky below','过了一万八千年，天地开辟：轻而清的阳气上升成为天，重而浊的阴气下沉成为地。','After 18,000 years heaven and earth opened: the light, clear yang rose to become heaven, the heavy, murky yin sank to become earth.','claim.v0310.china.pangu_separation','event.chinese.pangu_heaven_earth',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.chinese_pangu_yiwen_leiju.3','storyver.chinese.pangu_yiwen_leiju',3,'一天长高一丈','A zhang a day','从此天每天升高一丈，地每天加厚一丈，盘古也每天长高一丈。','From then on heaven rose a zhang each day, earth grew a zhang thicker, and Pangu grew a zhang taller.','claim.v0310.china.pangu_growth','event.chinese.pangu_heaven_earth',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','“盘古垂死化身为日月山川”出自另一部书，本故事不合并。','2026-10-09T00:30:00Z'),
('storyevent.v0310.chinese_nezha_xiyouji_ch4.1','storyver.chinese.nezha_xiyouji_ch4',1,'天兵来讨','Heaven sends its army','孙悟空发现“弼马温”只是个看马的小官，一气之下回到花果山，自称“齐天大圣”。','Discovering that his title merely made him a keeper of horses, Sun Wukong storms back to his mountain and calls himself Great Sage Equal to Heaven.','claim.v0310.china.nezha_title','event.chinese.nezha_fights_wukong',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.chinese_nezha_xiyouji_ch4.2','storyver.chinese.nezha_xiyouji_ch4',2,'三头六臂','Three heads, six arms','哪吒大喝一声，变成三头六臂，六只手各拿一件兵器打来。','Nezha gives a shout and becomes a figure with three heads and six arms, a weapon in every hand.','claim.v0310.china.nezha_form','event.chinese.nezha_fights_wukong',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.chinese_nezha_xiyouji_ch4.3','storyver.chinese.nezha_xiyouji_ch4',3,'毫毛分身','A hair becomes a double','两人斗得难分难解。','Neither can win.','claim.v0310.china.wukong_defeats_nezha','event.chinese.nezha_fights_wukong',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','这是小说情节，属于后世文学层。','2026-10-09T00:30:00Z'),
('storyevent.v0310.irish_mag_tuired_gray.1','storyver.irish.mag_tuired_gray',1,'达格达的大锅','The Dagda''s cauldron','达努神族带来了四件宝物，其中一件是从穆里亚斯城带来的达格达的大锅：凡是围着它吃饭的人，从没有一个是不饱足地离开的。','The Túatha Dé Danann brought four treasures.','claim.v0310.irish.dagda_cauldron','event.irish.second_battle_mag_tuired',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.irish_mag_tuired_gray.2','storyver.irish.mag_tuired_gray',2,'百艺之主来到塔拉','The master of all arts at Tara','鲁格来到塔拉的大门前，守门人问他会什么手艺。','Lug comes to the door of Tara, and the doorkeeper asks what art he brings.','claim.v0310.irish.lugh_samildanach','event.irish.second_battle_mag_tuired',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.irish_mag_tuired_gray.3','storyver.irish.mag_tuired_gray',3,'萨温节的河边','By the river at Samain','萨温节前后，达格达在乌恩辛河边遇见一个女人正在洗东西，一只脚踩在南岸，一只脚踩在北岸。','Around Samain the Dagda meets a woman washing at the river Unshin, one foot on the southern bank and one on the northern.','claim.v0310.irish.dagda_morrigan','event.irish.second_battle_mag_tuired',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.irish_mag_tuired_gray.4','storyver.irish.mag_tuired_gray',4,'第一次哀歌','The first keening','布里格是达格达的女儿，她和布雷斯的儿子鲁阿丹被派去刺杀铁匠戈伊布纽，却被戈伊布纽杀死。','Rúadán, son of Bres and of Bríg the Dagda''s daughter, is sent to kill the smith Goibniu and is killed instead.','claim.v0310.irish.brig_keens','event.irish.second_battle_mag_tuired',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','文本写作 Bríg；与数据库中“布里吉德”实体的对应依学界通行用法。','2026-10-09T00:30:00Z'),
('storyevent.v0310.irish_mag_tuired_gray.5','storyver.irish.mag_tuired_gray',5,'巴洛尔的毒眼','Balor''s deadly eye','弗魔族勇士巴洛尔有一只毒眼，只在战场上睁开，要四个人用把手才能抬起眼皮。','The Fomorian champion Balor has a deadly eye, opened only on the battlefield, its lid lifted by four men with a handle.','claim.v0310.irish.lugh_kills_balor','event.irish.second_battle_mag_tuired',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.irish_mag_tuired_gray.6','storyver.irish.mag_tuired_gray',6,'莫莉甘宣告胜利','The Morrígan proclaims the victory','战斗结束后，恩玛斯的女儿莫莉甘把这场大胜宣告给爱尔兰的王者高地、神丘里的众灵、各条大河与河口，然后又说出关于未来的预言。','When the battle is won, the Morrígan, daughter of Ernmas, proclaims the great victory to the royal heights of Ireland, its síd-hosts, its chief waters and river-mouths — and then speaks prophecy.','claim.v0310.irish.morrigan_proclaims','event.irish.second_battle_mag_tuired',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','预言诗的内容未逐句建模。','2026-10-09T00:30:00Z'),
('storyevent.v0310.slavic_kyiv_idols_pvl.1','storyver.slavic.kyiv_idols_pvl',1,'山岗上的神像','Idols on the hill','《往年纪事》980 年条记载：弗拉基米尔开始在基辅独自为王，就在宫殿庭院外的山岗上立起一排神像。','The Primary Chronicle''s annal for 980 records that when Volodimer began to reign alone in Kyiv, he set up a row of idols on the hill outside the palace courtyard.','claim.v0310.slavic.pvl_980_witness','event.slavic.kyiv_idols_980',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.slavic_kyiv_idols_pvl.2','storyver.slavic.kyiv_idols_pvl',2,'银头金须的佩伦','Perun with a silver head','最前面的是佩伦：木头雕成，头是银的，胡须是金的。','First stood Perun, carved of wood, with a silver head and a golden moustache.','claim.v060.slavic.perun_980_image','event.slavic.kyiv_idols_980',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.slavic_kyiv_idols_pvl.3','storyver.slavic.kyiv_idols_pvl',3,'名单最后的莫科什','Mokosh at the end of the list','接下来是霍尔斯、达日博格、斯特里博格、西马尔格尔，名单的最后一位是莫科什。','Then came Khors, Dazhbog, Stribog and Simargl, and last on the list, Mokosh.','claim.v0310.slavic.mokosh_980','event.slavic.kyiv_idols_980',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','关于莫科什职能的说法来自其他材料与现代研究，本故事不补写。','2026-10-09T00:30:00Z'),
('storyevent.v0310.slavic_kyiv_idols_pvl.4','storyver.slavic.kyiv_idols_pvl',4,'988 年：神像倒下','988: the idols fall','八年后，弗拉基米尔受洗，下令推倒这些神像：有的砍碎，有的烧掉。','Eight years later Volodimer was baptized and ordered the idols overthrown — some cut to pieces, others burned.','claim.v0310.slavic.perun_cast_down','event.slavic.kyiv_idols_980',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','这是皈依一方的记载，不是对斯拉夫宗教的中立描述。','2026-10-09T00:30:00Z'),
('storyevent.v0310.zoroastrian_mihr_yasht_darmesteter.1','storyver.zoroastrian.mihr_yasht_darmesteter',1,'与造物主同样尊贵','As worthy as his maker','颂歌一开头，阿胡拉·马兹达对查拉图斯特拉说：我创造广阔牧场之主密特拉时，使他与我自己一样，值得献祭、值得祈祷。','The hymn opens with Ahura Mazda telling Zarathustra: when I created Mithra, lord of wide pastures, I made him as worthy of sacrifice and as worthy of prayer as myself.','claim.v0310.zoro.mithra_created',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.zoroastrian_mihr_yasht_darmesteter.2','storyver.zoroastrian.mihr_yasht_darmesteter',2,'不可背弃契约','Never break the contract','对密特拉说谎、背弃契约的恶人，会给整个国家带来死亡。','The wretch who lies to Mithra, breaking the contract, brings death upon the whole land.','claim.v0310.zoro.mithra_contract',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','“契约”是译者对 miθra 一词的理解，学界另有讨论。','2026-10-09T00:30:00Z'),
('storyevent.v0310.zoroastrian_mihr_yasht_darmesteter.3','storyver.zoroastrian.mihr_yasht_darmesteter',3,'千耳万眼','A thousand ears, ten thousand eyes','颂歌赞美密特拉说真话，是集会中的首领；他有一千只耳朵，一万只眼睛，什么都瞒不过他。','The hymn praises Mithra as truth-speaking, a chief in assemblies, with a thousand ears and ten thousand eyes — nothing escapes him.','claim.v0310.zoro.mithra_eyes',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.zoroastrian_mihr_yasht_darmesteter.4','storyver.zoroastrian.mihr_yasht_darmesteter',4,'越过哈拉山','Over Mount Hara','每天清晨，他是天上诸神中第一个越过哈拉山的，比不朽的、驾着快马的太阳还要早。','Each morning he is the first of the heavenly gods to reach over Mount Hara, ahead of the undying, swift-horsed sun.','claim.v0310.zoro.mithra_hara',NULL,NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.zoroastrian_vd1_darmesteter.1','storyver.zoroastrian.vd1_darmesteter',1,'第一片良地','The first good land','阿胡拉·马兹达说：我所创造的良地中，第一片是雅利安瓦伊贾，在善河岱提亚旁边。','Ahura Mazda says: the first of the good lands I created was Airyana Vaejah, by the good river Daitya.','claim.v0310.zoro.airyana_vaejah','event.zoroastrian.sixteen_lands','place.zoroastrian.airyana_vaejah','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','雅利安瓦伊贾不映射为现代坐标。','2026-10-09T00:30:00Z'),
('storyevent.v0310.zoroastrian_vd1_darmesteter.2','storyver.zoroastrian.vd1_darmesteter',2,'全然是死亡的对手','The one who is all death','随后，“全然是死亡”的安格拉·曼纽来了，他针对这片良地造出了河中之蛇和寒冬，那是恶魔们的作品。','Then came Angra Mainyu, who is all death, and against it he counter-created the serpent in the river and winter, a work of the daevas.','claim.v0310.zoro.angra_counter','event.zoroastrian.sixteen_lands','place.zoroastrian.airyana_vaejah','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','神话地点不推测坐标。','2026-10-09T00:30:00Z'),
('storyevent.v0310.zoroastrian_vd1_darmesteter.3','storyver.zoroastrian.vd1_darmesteter',3,'十六地，十六灾','Sixteen lands, sixteen plagues','名单一片接一片地继续：第二片是粟特人居住的平原，安格拉·曼纽就造出蝗虫。','The list goes on land by land: the second is the plain where the Sughdhas dwell, and Angra Mainyu makes the locust.','claim.v0310.zoro.locust','event.zoroastrian.sixteen_lands','place.zoroastrian.airyana_vaejah','MYTHIC_PLACE','NO_COORDINATE','SOURCE_BACKED','译者认为这是宗教地理，混合了神话之地与真实国家；只有部分地名可以确认。','2026-10-09T00:30:00Z'),
('storyevent.v0310.hawaiian_pele_nps.1','storyver.hawaiian.pele_nps',1,'生在卡希基','Born in Kahiki','国家公园管理局介绍说，按照口述传统，佩蕾是夏威夷的火山之神，是一股自然之力，也是这些火山地貌的创造者。','The National Park Service explains that, in oral history, Pele is the Hawaiian volcano deity, an elemental force and the creator of these volcanic landscapes.','claim.v0310.hawaii.pele_kahiki','event.hawaiian.pele_journey','site.hawaii.halemaumau','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-09T00:30:00Z'),
('storyevent.v0310.hawaiian_pele_nps.2','storyver.hawaiian.pele_nps',2,'一路向东南','Island by island to the southeast','她一座岛一座岛地向东南迁移，寻找能安顿下来的地方。','She moved southeast through the islands, one after another, looking for a place to settle.','claim.v0310.hawaii.pele_southeast','event.hawaiian.pele_journey','site.hawaii.halemaumau','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','各岛上的具体经历因版本而异，本站不补写。','2026-10-09T00:30:00Z'),
('storyevent.v0310.hawaiian_pele_nps.3','storyver.hawaiian.pele_nps',3,'哈雷茂茂的家','A home in Halemaʻumaʻu','最后她来到基拉韦厄山顶的哈雷茂茂火山口，把这里定为永久的家。','At last she came to Halemaʻumaʻu crater at the summit of Kīlauea and made it her permanent home.','claim.v0310.hawaii.pele_halemaumau','event.hawaiian.pele_journey','site.hawaii.halemaumau','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','坐标只引用实体档案，不为单个情节推断位置。','2026-10-09T00:30:00Z'),
('storyevent.v0310.hawaiian_pele_nps.4','storyver.hawaiian.pele_nps',4,'经过她的土地','Passing through her land','在夏威夷传统中，经过佩蕾的土地要先请求她的许可。','In Hawaiian tradition it is customary to ask Pele''s permission to travel through her land, and the park asks visitors to behave respectfully in this sacred landscape.','claim.v0310.hawaii.pele_permission','event.hawaiian.pele_journey','site.hawaii.halemaumau','REAL_SITE','ENTITY_PROFILE_ONLY','SOURCE_BACKED','这里只讲公开概述；家族与地方传统不在收集范围。','2026-10-09T00:30:00Z'),
('storyevent.v0310.maori_creation_common_threads.1','storyver.maori.creation_common_threads',1,'从黑暗中出现','Out of darkness','Te Ara 写道：在毛利传统中，创世的核心行动是天与地的分离。','Te Ara writes that in Māori tradition the central act of creation is the separation of earth and sky.','claim.v0310.maori.rangi_papa_joined','event.maori.separation_rangi_papa',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED',NULL,'2026-10-09T00:30:00Z'),
('storyevent.v0310.maori_creation_common_threads.2','storyver.maori.creation_common_threads',2,'孩子们分开父母','The children part their parents','孩子们决定把父母分开。','The children decide to separate their parents.','claim.v0310.maori.ranginui_separated','event.maori.separation_rangi_papa',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','Te Ara 说明：在部分部族版本中，塔内在分开天地时起重要作用；本站不选定某一部族的说法。','2026-10-09T00:30:00Z'),
('storyevent.v0310.maori_creation_common_threads.3','storyver.maori.creation_common_threads',3,'自然的众神','Atua of the natural world','分离之后，孩子们成为自然各部分的神（atua）：塔内是森林之神，塔加罗阿是海洋之神，还有地震之神鲁奥莫科、风与天气之神塔维里马特阿。','After the separation the children become atua of different parts of nature: Tāne of the forests, Tangaroa of the sea, Rūaumoko of earthquakes, Tāwhirimātea of winds and weather.','claim.v0310.maori.tane_forests','event.maori.separation_rangi_papa',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','鲁奥莫科与塔维里马特阿尚未建立独立实体。','2026-10-09T00:30:00Z'),
('storyevent.v0310.maori_creation_common_threads.4','storyver.maori.creation_common_threads',4,'不是只有一个版本','Not a single version','Te Ara 也提醒，各部族的创世故事差异很大，特别是关于至高存在的角色。','Te Ara also cautions that tribal versions vary considerably, especially on the role of a supreme being.','claim.v0310.maori.diversity','event.maori.separation_rangi_papa',NULL,'UNSPECIFIED','NO_COORDINATE','SOURCE_BACKED','具名 iwi／hapū 版本仍为权限阻塞。','2026-10-09T00:30:00Z');

INSERT OR IGNORE INTO tradition_access_policies(
    id,entity_id,source_id,authority_name,community_context,access_level,permitted_scope,prohibited_scope,attribution_requirement,permission_contact_or_process,policy_basis,reviewed_at,notes
) VALUES
('policy.v0310.hawaii.pele_public','deity.hawaiian.pele','source.hawaii.pele.nps','U.S. National Park Service, Hawaiʻi Volcanoes National Park (public interpretation)','Native Hawaiian cultural practitioners and lineal descendants connected to Kīlauea','ATTRIBUTION_REQUIRED','Attributed summary of the NPS public pages on Pele and Holo Mai Pele.','Oli, mele, hula protocol, family or lineage traditions and any non-public cultural knowledge.','Cite the NPS pages and state that moʻolelo versions vary.','Seek guidance from Native Hawaiian cultural practitioners or community organizations before adding any further material.','Living tradition with a sacred landscape; NPS states that versions vary and asks visitors to show respect.','2026-10-09','v0.31 adds only the park''s public summary.'),
('policy.v0310.oshun.public_heritage','deity.yoruba.oshun','source.unesco.osun_osogbo.1118','UNESCO World Heritage Centre public record','Osogbo and wider Yoruba communities','PUBLIC_CONTEXT','The public World Heritage description of the grove and its association with Osun.','Festival rites, oríkì, divination verses and lineage knowledge.','Cite UNESCO property 1118.',NULL,'Official public heritage description.','2026-10-09','v0.31 card-level facts only.'),
('policy.v0310.oshun.living_practice','deity.yoruba.oshun','source.unesco.osun_osogbo.1118','Osun-Osogbo custodians and priesthood','Living Yoruba and diaspora Ọ̀ṣun devotion','PERMISSION_REQUIRED','None beyond the public heritage record until authorized.','Narratives, praise poetry, ritual and festival detail drawn from living practice.',NULL,'Request through the grove''s recognized custodial institutions.','Living religious practice; heritage listing is not permission to publish narratives.','2026-10-09','Blocks Ọ̀ṣun story expansion only, not the rest of the batch.'),
('policy.v0310.ogun.permission','deity.yoruba.ogun','source.yoruba.ifa.unesco','Relevant Yorùbá and diaspora custodial communities','Living Yorùbá religious traditions','PERMISSION_REQUIRED','Name, civilization link and a note that no public story has been published here.','Oríkì, Ifá verses, ritual and lineage narratives without named community authorization.',NULL,'Seek a named, public, community-led authority with an explicit publication scope.','No source with community permission has been identified; Ifá corpus material is already DO_NOT_COLLECT.','2026-10-09','The ogun story card shows this boundary instead of an invented story.'),
('policy.v0310.olodumare.permission','deity.yoruba.olodumare','source.yoruba.ifa.unesco','Relevant Yorùbá and diaspora custodial communities','Living Yorùbá religious traditions','PERMISSION_REQUIRED','Name, civilization link and a note that no public story has been published here.','Oríkì, Ifá verses, ritual and lineage narratives without named community authorization.',NULL,'Seek a named, public, community-led authority with an explicit publication scope.','No source with community permission has been identified; Ifá corpus material is already DO_NOT_COLLECT.','2026-10-09','The olodumare story card shows this boundary instead of an invented story.');

UPDATE entities SET description='徐整《三五历纪》佚文中的盘古：生于如鸡子的混沌之中，天地分开时日长一丈。 / Pangu as quoted from Xu Zheng''s lost Sanwu liji: born in an egg-like chaos, he grows a zhang a day as heaven and earth separate.',updated_at='2026-10-09T00:30:00Z' WHERE id='being.chinese.pangu' AND (description IS NULL OR description='');
