INSERT OR IGNORE INTO explorer_feature_registry(
    feature_code,title_zh,title_en,feature_group,data_basis,evidence_caveat,status,introduced_in,display_order,updated_at,notes
) VALUES
('deity_story_cards','神祇故事卡','Deity story cards','STORY_READING','Build-time cards for every deity-classified entity: linked story versions, evidence-backed claim beats and access policies.','A card never adds facts: each beat is an existing claim with evidence, and permission-limited deities show their boundary instead of a story.','ACTIVE','v0.31.0',330,'2026-10-09T00:30:00Z','Every deity has a card; Ogun and Olodumare cards are permission-limited.'),
('storyteller_mode','讲故事模式','Storyteller mode','STORY_READING','Full-screen, one-beat-at-a-time presentation of story sections and deity-card beats from the public snapshot.','Source notes and uncertainty notes stay one tap away on every beat.','ACTIVE','v0.31.0',340,'2026-10-09T00:30:00Z','Keyboard, swipe and on-screen controls; preferences stay on the device.');

